/// The real engine reply for a card spanning two repos (the fixture's `spanningRepos`, which `test/repos.targets.test.ts`
/// compares with real output): the card names repo A, and its second row is repo B's `main`. A has a `main` too, so
/// resolving B's row in A's facts would link it to the wrong repository.
#[test]
fn t6_a_row_from_another_repo_gets_no_branch_link_and_the_cards_own_row_keeps_its_link() {
    let span = vectors()["spanningRepos"].clone();
    let (reply, facts) = (span["reply"].clone(), span["actionFacts"].clone());
    let a = reply["labels"][0]["repoKey"].as_str().unwrap().to_string();
    assert_eq!(facts[0]["repoKey"], json!(a), "the card names repo A");
    assert_eq!(reply["labels"][0]["rows"][1]["name"], json!("main"), "B's row");
    assert_eq!(facts[0]["remoteBranches"][1]["name"], json!("main"), "A has a main of its own");
    let own = reply["labels"][0]["rows"][0]["commits"][0]["sha"].as_str().unwrap().to_string();
    let out = minted(&reply, &facts);
    assert_eq!(shape(&out.0, "did", "gui"), vec!["branch@0".to_string(), format!("commit@0:{own}")]);
    assert_eq!(held_of(&out, "did", "gui", "branch"),
        TargetFacts::Branch { owner: "org".into(), repo: "a".into(), remote: "origin".into(), remote_branch: "a-work".into() });
}

