#[test]
fn t6_upstreamless_branch_and_default_rows_need_exactly_one_remote_branch_at_the_real_tip() {
    for kind in ["branch", "default"] {
        let (mut reply, mut facts) = fx();
        with_rows(&mut reply, json!([{ "kind": kind, "name": "solo", "push": null, "commits": [commit(PUSHED)] }]));
        facts[0]["branches"] = json!([local_branch("solo", None, Some(OTHER))]);
        let entry = |remote: &str, name: &str| json!({ "remote": remote, "name": name, "sha": OTHER });
        // The same name at the same tip keeps its link.
        facts[0]["remoteBranches"] = json!([entry("origin", "solo")]);
        let out = minted(&reply, &facts);
        assert_eq!(held_of(&out, "did", "gui", "branch"),
            TargetFacts::Branch { owner: "org".into(), repo: "repo".into(), remote: "origin".into(), remote_branch: "solo".into() }, "{kind}");
        // A shared tip alone is a coincidence: `git checkout -b solo` at `origin/main` is not `main`.
        facts[0]["remoteBranches"] = json!([entry("origin", "main")]);
        assert!(!did(&reply, &facts).iter().any(|w| w.starts_with("branch")), "{kind}: another name at the tip");
        // The same name at another commit: the remote branch is not this branch's tip.
        facts[0]["remoteBranches"] = json!([{ "remote": "origin", "name": "solo", "sha": PUSHED }]);
        assert!(!did(&reply, &facts).iter().any(|w| w.starts_with("branch")), "{kind}: the same name at another tip");
        // The same name at the same tip on two remotes: no guess.
        facts[0]["remotes"].as_array_mut().unwrap().push(remote_entry("fork", "fork-org"));
        facts[0]["remoteBranches"] = json!([entry("origin", "solo"), entry("fork", "solo")]);
        assert!(!did(&reply, &facts).iter().any(|w| w.starts_with("branch")), "{kind}: two remotes hold it");
        facts[0]["remoteBranches"] = json!([]);
        assert!(!did(&reply, &facts).iter().any(|w| w.starts_with("branch")), "{kind}: none at the tip");
        facts[0]["remoteBranches"] = Value::Null;
        assert!(!did(&reply, &facts).iter().any(|w| w.starts_with("branch")), "{kind}: the list is unknown");
        facts[0]["remoteBranches"] = json!([entry("origin", "solo")]);
        facts[0]["branches"] = json!([local_branch("solo", None, None)]);
        assert!(!did(&reply, &facts).iter().any(|w| w.starts_with("branch")), "{kind}: the tip is unknown");
    }
}

