#[test]
fn t6_a_branch_row_with_an_upstream_needs_that_exact_remote_branch_to_exist() {
    let (mut reply, mut facts) = fx();
    with_rows(&mut reply, json!([{ "kind": "branch", "name": "local", "push": null, "commits": [commit(PUSHED)] }]));
    facts[0]["pushesToUpstream"] = json!(true);
    facts[0]["branches"] = json!([local_branch("local", Some(("origin", "differs")), Some(OTHER))]);
    facts[0]["remoteBranches"] = json!([{ "remote": "origin", "name": "differs", "sha": PUSHED }]);
    let out = minted(&reply, &facts);
    assert_eq!(held_of(&out, "did", "gui", "branch"),
        TargetFacts::Branch { owner: "org".into(), repo: "repo".into(), remote: "origin".into(), remote_branch: "differs".into() }, "the upstream's name, not the local one");
    // Gone from the remote, or never pushed there, even with a remote branch of the local name.
    facts[0]["remoteBranches"] = json!([{ "remote": "origin", "name": "local", "sha": OTHER }]);
    assert!(!did(&reply, &facts).iter().any(|w| w.starts_with("branch")));
    // A half-known upstream, a `.` upstream, an unlisted remote and a branch that failed the ref check.
    facts[0]["remoteBranches"] = json!([{ "remote": "origin", "name": "differs", "sha": PUSHED }]);
    for branch in [
        local_branch("local", None, None),
        json!({ "name": "local", "upstreamRemote": "origin", "upstreamBranch": null, "pushRemote": null, "remoteFactsUnknown": false, "checkoutPath": null, "refFormatOk": true, "tip": OTHER }),
        local_branch("local", Some((".", "differs")), Some(OTHER)),
        local_branch("local", Some(("nowhere", "differs")), Some(OTHER)),
        json!({ "name": "local", "upstreamRemote": "origin", "upstreamBranch": "differs", "pushRemote": null, "remoteFactsUnknown": false, "checkoutPath": null, "refFormatOk": false, "tip": OTHER }),
    ] {
        facts[0]["branches"] = json!([branch]);
        assert!(!did(&reply, &facts).iter().any(|w| w.starts_with("branch")), "{branch}");
    }
}

#[test]
fn t6_a_remote_branch_row_must_equal_exactly_one_remote_plus_name_and_is_never_split() {
    let (mut reply, mut facts) = fx();
    let row = |name: &str| json!([{ "kind": "remoteBranch", "name": name, "commits": [commit(PUSHED)] }]);
    facts[0]["remotes"] = json!([remote_entry("team", "team-org"), remote_entry("team/fork", "fork-org")]);
    // Only the longer remote holds it: a split at the first slash would pick the wrong repository.
    with_rows(&mut reply, row("team/fork/y"));
    facts[0]["remoteBranches"] = json!([{ "remote": "team/fork", "name": "y", "sha": OTHER }]);
    assert_eq!(held_of(&minted(&reply, &facts), "did", "gui", "branch"),
        TargetFacts::Branch { owner: "fork-org".into(), repo: "repo".into(), remote: "team/fork".into(), remote_branch: "y".into() });
    // Both readings exist: it could be either repository.
    facts[0]["remoteBranches"] = json!([{ "remote": "team/fork", "name": "y", "sha": OTHER }, { "remote": "team", "name": "fork/y", "sha": PUSHED }]);
    assert_eq!(did(&reply, &facts), Vec::<String>::new());
    // Not listed, the list unknown, a redacted name and a remote with no GitHub repository.
    facts[0]["remoteBranches"] = json!([{ "remote": "team", "name": "other", "sha": OTHER }]);
    assert_eq!(did(&reply, &facts), Vec::<String>::new());
    facts[0]["remoteBranches"] = Value::Null;
    assert_eq!(did(&reply, &facts), Vec::<String>::new());
    facts[0]["remoteBranches"] = json!([{ "remote": "team", "name": "[redacted]", "sha": OTHER }]);
    with_rows(&mut reply, row("team/[redacted]"));
    assert_eq!(did(&reply, &facts), Vec::<String>::new());
    with_rows(&mut reply, row("team/z"));
    facts[0]["remoteBranches"] = json!([{ "remote": "team", "name": "z", "sha": OTHER }]);
    facts[0]["remotes"][0]["github"] = Value::Null;
    assert_eq!(did(&reply, &facts), Vec::<String>::new());
}

