#[test]
fn t6_a_commit_needs_a_unique_reachable_remote_or_its_rows_established_one() {
    let (mut reply, mut facts) = fx();
    let row = json!([{ "kind": "branch", "name": "feature/contract", "push": null, "commits": [commit(PUSHED)] }]);
    with_rows(&mut reply, row);
    facts[0]["remotes"].as_array_mut().unwrap().push(remote_entry("fork", "fork-org"));
    let reach = |list: Value| json!([{ "sha": PUSHED, "remotes": list }]);
    // On both remotes: the row's established remote decides.
    facts[0]["reachableRemotes"] = reach(json!(["fork", "origin"]));
    let out = minted(&reply, &facts);
    assert_eq!(held_of(&out, "did", "gui", "commit"), TargetFacts::Commit { owner: "org".into(), repo: "repo".into(), remote: "origin".into(), sha: PUSHED.into() });
    // Unique, on the other remote: that remote's repository.
    facts[0]["reachableRemotes"] = reach(json!(["fork"]));
    let out = minted(&reply, &facts);
    assert_eq!(held_of(&out, "did", "gui", "commit"), TargetFacts::Commit { owner: "fork-org".into(), repo: "repo".into(), remote: "fork".into(), sha: PUSHED.into() });
    // Reachable nowhere, unknown, no reach entry, or the whole list unknown.
    let branch_only = vec!["branch@0".to_string()];
    facts[0]["reachableRemotes"] = reach(json!([]));
    assert_eq!(did(&reply, &facts), branch_only);
    facts[0]["reachableRemotes"] = reach(Value::Null);
    assert_eq!(did(&reply, &facts), branch_only);
    facts[0]["reachableRemotes"] = json!([]);
    assert_eq!(did(&reply, &facts), Vec::<String>::new(), "no entry for its commit: not shown to be this repo's row");
    facts[0]["reachableRemotes"] = Value::Null;
    assert_eq!(did(&reply, &facts), Vec::<String>::new(), "the list is unknown");
    // On both, with no established remote on the row: ambiguous, no guess.
    facts[0]["reachableRemotes"] = reach(json!(["fork", "origin"]));
    with_rows(&mut reply, json!([{ "kind": "detached", "commits": [commit(PUSHED)] }]));
    assert_eq!(did(&reply, &facts), Vec::<String>::new());
    // Not a full 40-hex id, even when the facts claim it.
    facts[0]["reachableRemotes"] = json!([{ "sha": "abc1234", "remotes": ["origin"] }]);
    with_rows(&mut reply, json!([{ "kind": "detached", "commits": [commit("abc1234")] }]));
    assert_eq!(did(&reply, &facts), Vec::<String>::new());
}

#[test]
fn t6_a_pr_row_is_open_pr_only_on_one_remotes_evidence_within_its_own_commits() {
    let (mut reply, mut facts) = fx();
    let evidence = |remote: &str, sha: &str| json!({ "number": 12, "sha": sha, "remote": remote, "method": "squash" });
    let row = |number: Value, sha: &str| json!([{ "kind": "pr", "number": number, "title": "", "commits": [commit(sha)] }]);
    with_rows(&mut reply, row(json!(12), MERGED));
    assert_eq!(did(&reply, &facts)[0], "pr@0", "squash evidence counts as well as merge");
    facts[0]["remotes"].as_array_mut().unwrap().push(remote_entry("fork", "fork-org"));
    facts[0]["prEvidence"] = json!([evidence("origin", MERGED), evidence("fork", MERGED)]);
    assert!(!did(&reply, &facts).iter().any(|w| w.starts_with("pr")), "a synced fork holds the evidence too");
    // What the engine reports for a remote with no known default that holds the evidence commit (`src/repos/reach.ts`).
    facts[0]["remotes"][1]["defaultBranch"] = Value::Null;
    assert!(!did(&reply, &facts).iter().any(|w| w.starts_with("pr")), "a synced fork with no upstream/HEAD");
    facts[0]["prEvidence"] = json!([evidence("origin", MERGED)]);
    assert_eq!(did(&reply, &facts)[0], "pr@0", "the same remote, not holding the evidence commit");
    facts[0]["prEvidence"] = json!([evidence("origin", OTHER)]);
    assert!(!did(&reply, &facts).iter().any(|w| w.starts_with("pr")), "evidence for a commit outside this row");
    facts[0]["prEvidence"] = Value::Null;
    assert!(!did(&reply, &facts).iter().any(|w| w.starts_with("pr")), "unknown evidence");
    facts[0]["prEvidence"] = json!([evidence("origin", MERGED)]);
    facts[0]["remotes"][0]["github"] = Value::Null;
    assert!(!did(&reply, &facts).iter().any(|w| w.starts_with("pr")), "no GitHub repository on that remote");
    let (mut reply, mut facts) = fx();
    facts[0]["prEvidence"][0]["number"] = json!(4_294_967_296u64);
    with_rows(&mut reply, row(json!(4_294_967_296u64), MERGED));
    assert!(!did(&reply, &facts).iter().any(|w| w.starts_with("pr")), "above the PR number bound");
}

