fn t6_where_you_left_off_follows_the_lines_state() {
    let line = |v: Value| json!([v]);
    let (mut reply, mut facts) = fx();
    // No push tag: nothing to copy.
    reply["branchLines"] = line(json!({ "key": "gui", "name": "feature/contract", "state": "live", "notPushed": 0, "neverPushed": false, "behind": 0 }));
    assert!(!left_off(&reply, &facts).contains(&"copy".to_string()));
    // Never pushed is a push tag.
    reply["branchLines"] = line(json!({ "key": "gui", "name": "feature/contract", "state": "live", "notPushed": 0, "neverPushed": true, "behind": 0 }));
    assert!(left_off(&reply, &facts).contains(&"copy".to_string()));
    // `noRemote`: the editor alone.
    reply["branchLines"] = line(json!({ "key": "gui", "name": "feature/contract", "state": "noRemote" }));
    assert_eq!(left_off(&reply, &facts), vec![format!("editor:{GUI_PROJECT}")]);
    // A missing branch: nothing, whatever the facts say.
    reply["branchLines"] = line(json!({ "key": "gui", "name": "feature/contract", "state": "missing" }));
    assert_eq!(left_off(&reply, &facts), Vec::<String>::new());
    // A redacted name, and a name the private facts do not hold: no name-based action.
    for name in ["[redacted]", "not-in-the-facts"] {
        reply["branchLines"] = line(json!({ "key": "gui", "name": name, "state": "live", "notPushed": 1, "neverPushed": false, "behind": 0 }));
        assert_eq!(left_off(&reply, &facts), Vec::<String>::new(), "{name}");
    }
    // No validated checkout: no editor, the rest stays.
    reply["branchLines"] = fx().0["branchLines"].clone();
    facts[0]["branches"][0]["checkoutPath"] = Value::Null;
    assert_eq!(left_off(&reply, &facts), vec!["branch", "compare:main", "copy"]);
}

