/// B2 `:46`: the tile copies its complete list. A partial list must never reach it.
#[test]
fn t6_the_tile_gets_no_handles_at_all_when_any_push_card_cannot_supply_its_own() {
    let (mut reply, mut facts) = fx();
    let view = json!({ "key": "rsecond", "name": "b", "state": "ok", "noRemote": false, "uncommitted": { "count": 0 }, "storeKey": "ssecond", "treeKey": "tb" });
    reply["repoViews"].as_array_mut().unwrap().push(view);
    let mut second = facts[0].clone();
    second["repoKey"] = json!("rsecond");
    second["branches"] = json!([local_branch("b", None, None)]); // what its card lists, so that it could copy
    let second_card = json!({ "repoKey": "rsecond", "storeKey": "ssecond", "firstLabel": null, "repoName": "b",
        "branches": [{ "name": "b", "commits": 1 }], "onDefault": null });
    reply["pushCards"].as_array_mut().unwrap().push(second_card);
    let (_, one_repo) = fx();
    facts.as_array_mut().unwrap().push(second.clone());
    let tile = |r: &Value, f: &Value| shape_all(&minted(r, f).0, "tile", "onlyHere");
    assert_eq!(tile(&reply, &facts), vec!["copy", "copy"], "the control: both repos' branches");
    // One repo's facts are missing: the other's own push card stays, and the tile has nothing.
    let out = minted(&reply, &one_repo);
    assert_eq!(shape(&out.0, "push", &format!("push:{RK}")), vec!["copy"]);
    assert_eq!(shape(&out.0, "push", "push:rsecond"), Vec::<String>::new());
    assert_eq!(shape_all(&out.0, "tile", "onlyHere"), Vec::<String>::new());
    // Listed unknown, no store key, and a repo with no remote that lists a branch.
    let mut listed = reply.clone();
    listed["unknownRepos"] = json!(["rsecond"]);
    assert_eq!(tile(&listed, &facts), Vec::<String>::new());
    let mut no_store = reply.clone();
    no_store["pushCards"][1].as_object_mut().unwrap().remove("storeKey");
    assert_eq!(tile(&no_store, &facts), Vec::<String>::new());
    let mut no_remote = reply.clone();
    no_remote["repoViews"][1]["noRemote"] = json!(true);
    assert_eq!(tile(&no_remote, &facts), Vec::<String>::new());
    // A repo with no remote and no branches to push costs nothing.
    let mut empty = no_remote.clone();
    empty["pushCards"][1]["branches"] = json!([]);
    assert_eq!(tile(&empty, &facts), vec!["copy"]);
}

