/// LOW 10: `mint` reads rows before `sanitize_reply`. Nothing here may panic, and no bad shape gives a handle.
#[test]
fn t6_a_malformed_document_never_panics_and_every_public_handle_is_held() {
    let (_, facts) = fx();
    let parsed = parse_action_facts(Some(facts));
    let junk = [json!(null), json!(7), json!("x"), json!([]), json!({}), json!([null]), json!([7]), json!([{}]), json!([[]]), json!({ "a": 1 })];
    for member in ["repoViews", "labels", "branchLines", "pushCards", "unknownRepos"] {
        for v in &junk {
            let (mut reply, _) = fx();
            reply[member] = v.clone();
            let _ = mint(reply.as_object().unwrap(), &parsed, 7);
            let mut gone = fx().0;
            gone.as_object_mut().unwrap().remove(member);
            let _ = mint(gone.as_object().unwrap(), &parsed, 7);
        }
    }
    for pointer in ["/labels/1/rows", "/labels/1/rows/0", "/labels/1/rows/0/commits", "/labels/1/rows/0/commits/0",
        "/labels/1/rows/0/commits/0/sha", "/labels/1/rows/0/kind", "/labels/1/rows/0/number", "/labels/1/rows/1/name",
        "/labels/1/key", "/labels/1/repoKey", "/branchLines/0", "/branchLines/0/key", "/branchLines/0/name",
        "/branchLines/0/state", "/pushCards/0", "/pushCards/0/repoKey", "/pushCards/0/storeKey", "/pushCards/0/branches",
        "/pushCards/0/branches/0", "/pushCards/0/branches/0/name", "/pushCards/0/onDefault", "/repoViews/0/key",
        "/repoViews/0/state", "/repoViews/0/noRemote", "/repoViews/0/storeKey"] {
        for v in &junk {
            let (mut reply, _) = fx();
            *reply.pointer_mut(pointer).unwrap_or_else(|| panic!("{pointer}")) = v.clone();
            let (cards, held) = mint(reply.as_object().unwrap(), &parsed, 7);
            assert_eq!(cards.iter().map(|c| c.handles.len()).sum::<usize>(), held.len(), "{pointer} = {v}");
            for c in &cards { assert!(!c.handles.is_empty(), "{pointer} = {v}: an empty card"); }
        }
    }
    // An out-of-range PR number, a bad sha and non-string names give no handle for that row.
    let (mut reply, facts) = fx();
    reply["labels"][1]["rows"][0]["number"] = json!(-1);
    assert!(!did(&reply, &facts).iter().any(|w| w.starts_with("pr")));
    let (mut reply, facts) = fx();
    reply["labels"][1]["rows"][1]["name"] = json!(9);
    assert!(!did(&reply, &facts).iter().any(|w| w.starts_with("branch")));
}

