/// Rust's total cap refuses only the repos past it. A shared file (the global config, on every repo) counts once.
#[cfg(unix)]
#[test]
fn the_total_cap_refuses_only_the_repos_past_it_and_counts_a_shared_file_once() {
    let scratch = common::ScratchDir::new("totalcap");
    let root = std::fs::canonicalize(&scratch.path).unwrap();
    let missing = json!({ "mtimeNs": "0", "size": "0", "kind": "missing", "target": null });
    let inputs = |prefix: &str, n: usize| -> Value {
        json!((0..n).map(|i| json!({ "path": root.join(format!("{prefix}/{i}")).to_str().unwrap(), "stamp": missing })).collect::<Vec<_>>())
    };
    let span = vectors()["spanningRepos"]["actionFacts"].clone();
    let keys = [span[0]["repoKey"].as_str().unwrap().to_string(), span[1]["repoKey"].as_str().unwrap().to_string()];
    let with = |first: Value, second: Value| {
        let mut f = span.clone();
        f[0]["statInputs"] = first;
        f[1]["statInputs"] = second;
        let parsed = parse_action_facts(Some(f));
        assert_eq!(parsed.len(), 2);
        accept_stat_inputs(&parsed, &B2StatInputs::default())
    };
    // One large repo beside a small one, in both orders: the small one still mints.
    let a = with(inputs("large", STAT_CAP + 1), inputs("small", 3));
    assert!(!a.holds(&keys[0]) && a.holds(&keys[1]));
    let a = with(inputs("small", 3), inputs("large", STAT_CAP + 1));
    assert!(a.holds(&keys[0]) && !a.holds(&keys[1]));
    // Together past the cap: the first fits and the second is refused.
    let a = with(inputs("one", STAT_CAP - 1), inputs("two", 5));
    assert!(a.holds(&keys[0]) && !a.holds(&keys[1]));
    // Both fit once the paths they share count once.
    let a = with(inputs("shared", STAT_CAP - 1), inputs("shared", STAT_CAP - 1));
    assert!(a.holds(&keys[0]) && a.holds(&keys[1]), "a shared path was counted twice");
}

/// A repo refused by the stat check still has its label keys: it must not make another repo's key look unique.
#[test]
fn a_refused_repo_still_makes_a_label_key_ambiguous_for_where_you_left_off() {
    let (mut reply, mut facts) = fx();
    reply["labels"] = json!([]);
    reply["pushCards"] = json!([]);
    let mut second = facts[0].clone();
    second["repoKey"] = json!("rother000000");
    second["path"] = json!("/fixture/other");
    facts.as_array_mut().unwrap().push(second);
    let mut view = reply["repoViews"][0].clone();
    view["key"] = json!("rother000000");
    reply["repoViews"].as_array_mut().unwrap().push(view);
    let parsed = parse_action_facts(Some(facts.clone()));
    assert_eq!(parsed.len(), 2);
    let doc = reply.as_object().unwrap();
    // Both repos list `gui` on a root: nothing, whichever of them was accepted.
    for only in [RK, "rother000000"] {
        let (cards, _) = mint_accepted(doc, &parsed, |key| key == only, 7);
        assert!(cards.iter().all(|c| c.card_kind.as_str() != "leftOff"), "{only}: {cards:?}");
    }
    // The other repo lists no such key, so the key is unique and the accepted repo's card mints.
    facts[1]["roots"] = json!([{ "root": "", "project": ROOT_PROJECT, "labelKeys": [], "displayLabel": null }]);
    facts[1]["cardKeys"] = json!([]);
    let parsed = parse_action_facts(Some(facts));
    let (cards, _) = mint_accepted(doc, &parsed, |key| key == RK, 7);
    assert!(cards.iter().any(|c| c.card_kind.as_str() == "leftOff"), "{cards:?}");
    // And it needs its own acceptance.
    let (cards, _) = mint_accepted(doc, &parsed, |key| key != RK, 7);
    assert!(cards.iter().all(|c| c.card_kind.as_str() != "leftOff"), "{cards:?}");
}


