/// The first handle of `target` on a card, as a click resolves it.
fn held(out: &(Vec<ActionCard>, HeldTargets), kind: &str, id: &str, target: &str) -> HeldTarget {
    let handle = out.0.iter().filter(|c| c.card_kind.as_str() == kind && c.card_id == id)
        .flat_map(|c| &c.handles).find(|h| h.target.as_str() == target)
        .unwrap_or_else(|| panic!("no {target} handle on {kind} {id}: {:?}", out.0));
    out.1[&handle.handle].clone()
}

/// A click with the links switch `on`: its reply as the webview reads it, and what the recording opener received.
fn click(h: Option<&HeldTarget>, on: bool) -> (Value, Vec<String>) {
    let opener = common::RecordingOpener::default();
    let reply = open_held(h, on, &opener);
    (serde_json::to_value(&reply).expect("a reply"), opener.urls())
}

fn opens(h: &HeldTarget, url: &str) {
    assert_eq!(click(Some(h), true), (json!({ "opened": true }), vec![url.to_string()]));
}

fn refuses(h: &HeldTarget, code: &str, why: &str) {
    assert_eq!(click(Some(h), true), (json!({ "refused": code }), vec![]), "{why}");
}

/// `h` as it would resolve over bent held facts: the click re-judges the target it was minted with against these.
fn over(h: &HeldTarget, facts: &Value) -> HeldTarget {
    let mut parsed = parse_action_facts(Some(facts.clone()));
    assert_eq!(parsed.len(), 1, "the bent facts still parse: {facts}");
    let mut h = h.clone();
    h.facts = std::sync::Arc::new(parsed.remove(0));
    h
}

/// A live Where-you-left-off line on `name`, whose upstream is `origin/<name>`, on a remote whose default is `default`.
fn line_on(name: &str, default: &str) -> (Value, Value) {
    let (mut reply, mut facts) = fx();
    reply["branchLines"] = json!([{ "key": "gui", "name": name, "state": "live", "notPushed": 1, "neverPushed": false, "behind": 0 }]);
    facts[0]["branches"] = json!([local_branch(name, Some(("origin", name)), Some(OTHER))]);
    facts[0]["remoteBranches"] = json!([{ "remote": "origin", "name": name, "sha": OTHER }]);
    facts[0]["remotes"][0]["defaultBranch"] = json!(default);
    (reply, facts)
}

