/// The engine's owner/repo rule, as the shared vectors state it (`github-target-vectors.json`), held by Rust's own check.
#[test]
fn t8_the_shared_vectors_agree_with_rusts_revalidation() {
    let doc: Value = serde_json::from_str(include_str!("fixtures/github-target-vectors.json")).expect("the vectors");
    let (mut accepted, mut refused) = (0, 0);
    for v in doc["github"].as_array().expect("the github vectors") {
        let url = v["url"].as_str().unwrap();
        if v["expected"].is_null() {
            // Two path segments on the plain host: only the owner/repo rule can have refused these. The credential
            // matcher stays in the engine (plan R2-O4), so its one vector is not Rust's to refuse.
            let Some(path) = url.strip_prefix("https://github.com/") else { continue };
            let parts: Vec<&str> = path.split('/').collect();
            if parts.len() != 2 || parts[1].starts_with("GHP_") {
                continue;
            }
            assert!(!is_github_name(parts[0], parts[1]), "{url}");
            refused += 1;
        } else {
            let (owner, repo) = (v["expected"]["owner"].as_str().unwrap(), v["expected"]["repo"].as_str().unwrap());
            assert!(is_github_name(owner, repo), "{url}");
            accepted += 1;
        }
    }
    assert!(accepted >= 7 && refused >= 5, "{accepted} accepted, {refused} refused: the vectors were read");
}

/// Plan §0, B2 final round 2: PR evidence counts repositories, not remotes. The mint and the click must agree.
#[test]
fn t8_pr_evidence_counts_distinct_repositories_not_remotes() {
    let (reply, facts) = fx();
    let out = minted(&reply, &facts);
    let pr = held(&out, "did", "gui", "pr");
    let holders = |second: Value| {
        let mut f = facts.clone();
        let name = second["name"].clone();
        f[0]["remotes"] = json!([facts[0]["remotes"][0], second]);
        f[0]["prEvidence"] = json!([
            { "number": 12, "sha": MERGED, "remote": "origin", "method": "merge" },
            { "number": 12, "sha": MERGED, "remote": name, "method": "merge" },
        ]);
        f
    };
    let no_default = |name: &str, owner: &str| {
        let mut r = remote_entry(name, owner);
        r["defaultBranch"] = Value::Null;
        r
    };
    // `origin` and `origin-ssh` for one repository: the button stays, on the first by name, and its click opens.
    for owner in ["org", "ORG"] {
        let same = holders(no_default("origin-ssh", owner));
        assert!(did(&reply, &same).contains(&"pr@0".to_string()), "{owner}: one repository");
        let again = minted(&reply, &same);
        assert_eq!(held_of(&again, "did", "gui", "pr"), TargetFacts::Pr { owner: "org".into(), repo: "repo".into(), remote: "origin".into(), number: 12 });
        opens(&over(&pr, &same), "https://github.com/org/repo/pull/12");
    }
    // The other name of that repository is an accepted destination too.
    let mut by_ssh = pr.clone();
    by_ssh.target = TargetFacts::Pr { owner: "org".into(), repo: "repo".into(), remote: "origin-ssh".into(), number: 12 };
    opens(&over(&by_ssh, &holders(no_default("origin-ssh", "org"))), "https://github.com/org/repo/pull/12");
    // The fork case stays refused: another repository, known default or none.
    for second in [no_default("upstream", "up-org"), remote_entry("upstream", "up-org")] {
        let fork = holders(second);
        assert!(!did(&reply, &fork).iter().any(|w| w.starts_with("pr")), "two repositories");
        refuses(&over(&pr, &fork), "ambiguous", "two repositories");
    }
    // A repo name that differs is another repository, too.
    let mut renamed = no_default("origin-ssh", "org");
    renamed["github"]["repo"] = json!("other");
    assert!(!did(&reply, &holders(renamed.clone())).iter().any(|w| w.starts_with("pr")), "another repo under one owner");
    refuses(&over(&pr, &holders(renamed)), "ambiguous", "another repo under one owner");
    // A holder that reads as no GitHub repository, as a remote with a known default can, is a repository of its own.
    let mut gitlab = remote_entry("gitlab", "org");
    gitlab["github"] = Value::Null;
    assert!(!did(&reply, &holders(gitlab.clone())).iter().any(|w| w.starts_with("pr")), "a known default elsewhere");
    refuses(&over(&pr, &holders(gitlab)), "ambiguous", "a known default elsewhere");
    // One repository holds it, but the target names a remote that does not: not the destination it was minted with.
    let same = holders(no_default("origin-ssh", "org"));
    let mut solo = same.clone();
    solo[0]["prEvidence"] = json!([{ "number": 12, "sha": MERGED, "remote": "origin-ssh", "method": "merge" }]);
    refuses(&over(&pr, &solo), "ambiguous", "evidence only under the repository's other remote");
}

#[test]
fn t8_a_pr_number_must_be_in_range_and_in_its_held_row() {
    let (mut reply, mut facts) = fx();
    let at_limit = 4_294_967_295u64;
    reply["labels"][1]["rows"][0]["number"] = json!(at_limit);
    facts[0]["prEvidence"][0]["number"] = json!(at_limit);
    let pr = held(&minted(&reply, &facts), "did", "gui", "pr");
    opens(&pr, "https://github.com/org/repo/pull/4294967295");
    // One past the limit: no handle, and a held target of that number refuses and makes no URL.
    reply["labels"][1]["rows"][0]["number"] = json!(at_limit + 1);
    facts[0]["prEvidence"][0]["number"] = json!(at_limit + 1);
    assert!(!shape(&minted(&reply, &facts).0, "did", "gui").contains(&"pr@0".to_string()));
    let mut over_limit = over(&pr, &facts);
    over_limit.target = TargetFacts::Pr { owner: "org".into(), repo: "repo".into(), remote: "origin".into(), number: at_limit + 1 };
    over_limit.row = Some(std::sync::Arc::new(reply["labels"][1]["rows"][0].clone()));
    assert_eq!(github_url(&over_limit.target), None);
    refuses(&over_limit, "invalid-target", "above 4294967295");
    let (reply, facts) = fx();
    let pr = held(&minted(&reply, &facts), "did", "gui", "pr");
    // Not this row's number, no row at all, and evidence only for a commit outside the row.
    let mut other = pr.clone();
    other.row = Some(std::sync::Arc::new(json!({ "kind": "pr", "number": 13, "commits": [commit(MERGED)] })));
    refuses(&other, "invalid-target", "another number's row");
    let mut no_row = pr.clone();
    no_row.row = None;
    refuses(&no_row, "invalid-target", "no held row");
    let mut outside = pr.clone();
    outside.row = Some(std::sync::Arc::new(json!({ "kind": "pr", "number": 12, "commits": [commit(OTHER)] })));
    refuses(&outside, "not-pushed", "the evidence is for a commit outside the row");
}

