/// The order that selects a remote (B2 `:85`), and `-u` by whether an upstream exists, never by the remote selected.
#[test]
fn t9_the_remote_is_selected_conservatively_and_u_follows_the_upstream() {
    let with_fork = |f: &mut Value| f["remotes"] = json!([f["remotes"][0], remote_entry("fork", "fork-org")]);
    let mut triangular = feature(Some(("origin", "feature")));
    triangular["pushRemote"] = json!("fork");
    wants_copy(copy_bent(vec![triangular], with_fork), &format!("{REPO} -- 'fork' 'feature'"), "pushRemote beats the upstream, and adds no -u");
    wants_copy(copy_bent(vec![feature(Some(("origin", "feature")))], |f| { with_fork(f); f["pushDefault"] = json!("fork"); }),
        &format!("{REPO} -- 'fork' 'feature'"), "pushDefault beats the upstream, and adds no -u");
    let mut named = feature(None);
    named["pushRemote"] = json!("fork");
    wants_copy(copy_bent(vec![named.clone()], with_fork), &format!("{REPO} -u -- 'fork' 'feature'"), "no upstream: -u, on the selected remote");
    let mut third = named;
    third["pushRemote"] = json!("origin");
    wants_copy(copy_bent(vec![third], |f| { with_fork(f); f["pushDefault"] = json!("fork"); }),
        &format!("{REPO} -u -- 'origin' 'feature'"), "pushRemote beats pushDefault");
    wants_copy(copy_bent(vec![feature(Some(("origin", "feature")))], with_fork), &format!("{REPO} -- 'origin' 'feature'"), "the upstream's remote among several");
}

#[test]
fn t9_unsafe_names_refuse_single_and_whole_copies() {
    for name in ["--receive-pack=x", "-x", "feat x", "feat$x", "a;b", "é", "a\u{202e}b", "a\tb", "a\nb", "[redacted]", "tag", "HEAD"] {
        let single = local_branch(name, Some(("origin", name)), None);
        wants_refusal(copy_bent(vec![single.clone()], |_| {}), "unsafe-name", name);
        let good = feature(Some(("origin", "feature")));
        wants_refusal(copy_bent(vec![good, single], |_| {}), "unsafe-name", &format!("{name} in a whole copy"));
    }
    // Close to those, and fine: only the literal operands are refused.
    wants_copy(copy_bent(vec![local_branch("tag/1", None, None)], |_| {}), &format!("{REPO} -u -- 'origin' 'tag/1'"), "tag/1");
    // The remote's own name is an operand too.
    for remote in ["--receive-pack=x", "-x", "o rigin", "o'x", "o\u{202e}x", "[redacted]"] {
        let mut b = feature(None);
        b["pushRemote"] = json!(remote);
        wants_refusal(copy_bent(vec![b.clone()], |f| f["remotes"] = json!([f["remotes"][0], remote_entry(remote, "org")])), "unsafe-name", remote);
        let good = feature(Some(("origin", "feature")));
        let mut other = b;
        other["name"] = json!("other");
        wants_refusal(copy_bent(vec![good, other], |f| f["remotes"] = json!([f["remotes"][0], remote_entry(remote, "org")])), "unsafe-name", remote);
    }
}

