#[test]
fn t9_ambiguous_is_any_fact_that_is_unknown_or_several_remotes_unresolved() {
    let up = || feature(Some(("origin", "feature")));
    wants_origin_copy(copy_bent(vec![feature(None)], |f| f["remotes"] = json!([f["remotes"][0], remote_entry("fork", "org")])),
        &format!("{REPO} -u -- 'origin' 'feature'"), "two remotes, none selected: origin (user decision 2026-11-05)");
    wants_refusal(copy_bent(vec![feature(None)], no_origin), "ambiguous", "two remotes, none selected, neither origin");
    for member in ["configSection", "url", "legacy", "push"] {
        wants_refusal(copy_bent(vec![up()], |f| f["remotes"][0][member] = Value::Null), "ambiguous", member);
    }
    let mut half = feature(None);
    half["upstreamRemote"] = json!("origin");
    wants_refusal(copy_bent(vec![half], |_| {}), "ambiguous", "an upstream remote and no branch");
    let mut half = feature(None);
    half["upstreamBranch"] = json!("feature");
    wants_refusal(copy_bent(vec![half], |_| {}), "ambiguous", "an upstream branch and no remote");
    // Sole-remote counting with the legacy entries or a section unknown.
    wants_refusal(copy_bent(vec![feature(None)], |f| f["legacyNames"] = Value::Null), "ambiguous", "the legacy names unknown");
    wants_refusal(copy_bent(vec![feature(None)], |f| f["remotes"][0]["configSection"] = Value::Null), "ambiguous", "a section unknown");
    // A selected or upstream name the facts do not list has no facts to go on.
    wants_refusal(copy_bent(vec![feature(Some(("unlisted", "feature")))], |_| {}), "ambiguous", "an unlisted upstream");
    let mut pushes = feature(Some(("unlisted", "feature")));
    pushes["pushRemote"] = json!("origin");
    wants_refusal(copy_bent(vec![pushes], |_| {}), "ambiguous", "the upstream's remote is unlisted though another is selected");
}

/// B2 `:90`: a remote the facts leave out for its name is still a remote, so what is left cannot be the sole one. `upstream`
/// plus `my fork` must not become a guessed `push -u -- 'upstream' 'x'`. A name that selection reads needs no count.
#[test]
fn t9_a_left_out_remote_name_leaves_the_sole_remote_unresolved() {
    let left_out = |f: &mut Value| f["omittedRemotes"] = json!(true);
    wants_copy(copy_bent(vec![feature(None)], |_| {}), &format!("{REPO} -u -- 'origin' 'feature'"), "the control: origin alone is the sole remote");
    wants_refusal(copy_bent(vec![feature(None)], left_out), "ambiguous", "origin and a left-out name");
    wants_refusal(copy_bent(vec![feature(None)], |f| { left_out(f); f["remotes"] = json!([]); }), "ambiguous", "only a left-out name: not no-remote");
    wants_copy(copy_bent(vec![feature(Some(("origin", "feature")))], left_out), &format!("{REPO} -- 'origin' 'feature'"), "an upstream names its remote");
    wants_copy(copy_bent(vec![feature(None)], |f| { left_out(f); f["pushDefault"] = json!("origin"); }),
        &format!("{REPO} -u -- 'origin' 'feature'"), "pushDefault names its remote");
    let mut named = feature(None);
    named["pushRemote"] = json!("origin");
    wants_copy(copy_bent(vec![named], left_out), &format!("{REPO} -u -- 'origin' 'feature'"), "pushRemote names its remote");
}

#[test]
fn t9_name_mismatch_is_anything_that_can_retarget_the_push() {
    let up = || feature(Some(("origin", "feature")));
    let real = |f: &mut Value| f["pushesToUpstream"] = json!(true);
    wants_refusal(copy_bent(vec![feature(Some(("origin", "other")))], real), "name-mismatch", "a differently named upstream that is its destination");
    wants_refusal(copy_bent(vec![feature(Some(("origin", "refs/tags/x")))], real), "name-mismatch", "a destination that is no branch");
    // Only where it started: the text names the branch's own name, so nothing retargets it, and -u would move the upstream.
    let own = format!("{REPO} -- 'origin' 'feature'");
    wants_copy(copy_bent(vec![feature(Some(("origin", "other")))], |_| {}), &own, "a differently named upstream, not its destination");
    wants_copy(copy_bent(vec![feature(Some(("origin", "refs/tags/x")))], |_| {}), &own, "no branch, and not its destination");
    // The refspec case of B2 `:124`: `remote.origin.push` set, whatever it says.
    wants_refusal(copy_bent(vec![up()], |f| f["remotes"][0]["push"] = json!(true)), "name-mismatch", "a push refspec");
}

/// B2 `:125`'s legacy fixture, as the facts report it: `remotes/origin` or `branches/origin` is one presence fact.
#[test]
fn t9_a_legacy_entry_is_never_copied_and_is_never_no_remote() {
    let legacy = |section: bool, url: bool| move |f: &mut Value| {
        f["legacyNames"] = json!(["origin"]);
        f["remotes"][0]["legacy"] = json!(true);
        f["remotes"][0]["configSection"] = json!(section);
        f["remotes"][0]["url"] = json!(url);
    };
    let up = || feature(Some(("origin", "feature")));
    // (a) no `[remote "origin"]` section at all: selected as the upstream's remote, then as the sole remote.
    wants_refusal(copy_bent(vec![up()], legacy(false, false)), "name-mismatch", "(a) as the upstream's remote");
    wants_refusal(copy_bent(vec![feature(None)], legacy(false, false)), "name-mismatch", "(a) as the sole remote");
    // (b) a section with `url` present.
    wants_refusal(copy_bent(vec![up()], legacy(true, true)), "name-mismatch", "(b) with a url");
    wants_refusal(copy_bent(vec![feature(None)], legacy(true, true)), "name-mismatch", "(b) as the sole remote");
    // A whole copy.
    wants_refusal(copy_bent(vec![local_branch("solo", None, None), up()], legacy(true, true)), "name-mismatch", "whole copy");
    // A legacy-only name counts as a remote, so beside a configured one there is no sole remote: `origin` if it is that one,
    // and otherwise nothing.
    let old = json!({ "name": "old", "transport": null, "github": null, "vcs": false, "push": false,
        "configSection": false, "url": false, "legacy": true, "defaultBranch": null });
    wants_origin_copy(copy_bent(vec![feature(None)], |f| {
        f["legacyNames"] = json!(["old"]);
        f["remotes"] = json!([f["remotes"][0], old]);
    }), &format!("{REPO} -u -- 'origin' 'feature'"), "a legacy-only name beside a configured origin");
    wants_refusal(copy_bent(vec![feature(None)], |f| {
        f["legacyNames"] = json!(["old"]);
        f["remotes"] = json!([remote_entry("fork", "org"), old]);
    }), "ambiguous", "a legacy-only name beside a configured remote that is not origin");
    // The upstream's name counts too, when another remote is the one selected.
    let mut triangular = up();
    triangular["pushRemote"] = json!("fork");
    wants_refusal(copy_bent(vec![triangular], |f| {
        f["legacyNames"] = json!(["origin"]);
        f["remotes"][0]["legacy"] = json!(true);
        f["remotes"] = json!([f["remotes"][0], remote_entry("fork", "org")]);
    }), "name-mismatch", "a legacy upstream beside a clean pushRemote");
}

#[test]
fn t9_transport_is_any_verdict_but_a_plain_network_one() {
    let up = || feature(Some(("origin", "feature")));
    wants_refusal(copy_bent(vec![up()], |f| f["remotes"][0]["transport"] = json!("refused")), "transport", "refused");
    wants_refusal(copy_bent(vec![up()], |f| f["remotes"][0]["transport"] = Value::Null), "transport", "no verdict");
    wants_refusal(copy_bent(vec![up()], |f| f["remotes"][0]["vcs"] = json!(true)), "transport", "vcs set");
    wants_refusal(copy_bent(vec![up()], |f| f["remotes"][0]["vcs"] = Value::Null), "transport", "vcs unknown");
    // The upstream's transport is not asked: only the selected remote's push is what runs.
    let mut triangular = up();
    triangular["pushRemote"] = json!("fork");
    wants_copy(copy_bent(vec![triangular], |f| {
        f["remotes"][0]["transport"] = json!("refused");
        f["remotes"] = json!([f["remotes"][0], remote_entry("fork", "org")]);
    }), &format!("{REPO} -- 'fork' 'feature'"), "the selected remote decides");
}

/// B2 `:127`, every refusal-order pin, and the order's own stages one against the next.
#[test]
fn t9_the_refusal_order_is_fixed() {
    let up = || feature(Some(("origin", "feature")));
    wants_refusal(copy_bent(vec![up()], |f| {
        f["remotes"][0]["push"] = json!(true);
        f["remotes"][0]["transport"] = json!("refused");
    }), "name-mismatch", "a refspec and an http:// destination");
    wants_refusal(copy_bent(vec![local_branch("tag", None, None)], |f| f["remotes"] = json!([])), "unsafe-name", "an unsafe name and no remote");
    // A whole copy whose second branch is ambiguous (an upstream remote with no branch) and third is transport.
    let (_, mut facts) = push_of(vec![
        feature(Some(("origin", "feature"))),
        { let mut b = local_branch("second", None, None); b["upstreamRemote"] = json!("origin"); b },
        { let mut b = local_branch("third", Some(("bad", "third")), None); b["pushRemote"] = json!("bad"); b },
    ]);
    let mut bad = remote_entry("bad", "org");
    bad["transport"] = json!("refused");
    facts[0]["remotes"] = json!([facts[0]["remotes"][0], bad]);
    let whole = held_over(&["feature", "second", "third"], &facts);
    wants_refusal(copied(&whole), "ambiguous", "the second branch's refusal, not the third's");
    // The order is the card's, whatever order the request came in.
    let reversed: Vec<Option<HeldTarget>> = whole.iter().rev().cloned().collect();
    wants_refusal(copied(&reversed), "ambiguous", "reversed: still the card's second branch");
    // An absent configured URL, with and without a section, by what is known of the legacy entry.
    for section in [true, false] {
        let absent = |legacy: Value| move |f: &mut Value| {
            f["remotes"][0]["configSection"] = json!(section);
            f["remotes"][0]["url"] = json!(false);
            f["remotes"][0]["legacy"] = legacy.clone();
            if legacy == json!(true) { f["legacyNames"] = json!(["origin"]); }
            if legacy.is_null() { f["legacyNames"] = Value::Null; }
        };
        wants_refusal(copy_bent(vec![up()], absent(json!(false))), "no-remote", &format!("no legacy entry, section {section}"));
        wants_refusal(copy_bent(vec![up()], absent(Value::Null)), "ambiguous", &format!("legacy unknown, section {section}"));
        wants_refusal(copy_bent(vec![up()], absent(json!(true))), "name-mismatch", &format!("a legacy entry, section {section}"));
    }
    // Stage against stage, each pair on one branch.
    wants_refusal(copy_bent(vec![up()], |f| f["remotes"] = Value::Null), "unknown-repo", "the remotes unknown");
    for name in ["tag", "-x", "a b"] {
        let (_, mut facts) = push_of(vec![local_branch(name, None, None)]);
        facts[0]["remotes"] = Value::Null;
        wants_refusal(copied(&held_over(&[name], &facts)), "unknown-repo", "unknown-repo before unsafe-name");
    }
    wants_refusal(copy_bent(vec![up()], |f| { f["remotes"][0]["url"] = json!(false); f["remotes"][0]["push"] = Value::Null; }), "no-remote", "no-remote before ambiguous");
    wants_refusal(copy_bent(vec![feature(Some(("origin", "other")))], |f| f["remotes"][0]["push"] = Value::Null), "ambiguous", "ambiguous before name-mismatch");
    wants_refusal(copy_bent(vec![feature(Some(("origin", "other")))], |f| { f["pushesToUpstream"] = json!(true); f["remotes"][0]["vcs"] = json!(true); }), "name-mismatch", "name-mismatch before transport");
    assert_eq!(judge_copy_branch(&parse_action_facts(Some(fx().1)).remove(0), "feature/contract").map(|c| c.text()),
        Ok("git -C '/fixture/repo' push -- 'origin' 'feature/contract'".to_string()));
    assert_eq!(judge_copy_branch(&parse_action_facts(Some(fx().1)).remove(0), "no-such-branch").map(|c| c.text()), Err(CopyRefusal::UnsafeName));
}

#[test]
fn t9_the_list_checks_come_first_and_refuse_the_whole_copy() {
    wants_refusal(copied(&[]), "unsafe-name", "an empty list");
    let (reply, facts) = fx();
    let out = minted(&reply, &facts);
    let card = on_card(&out, "push", CARD);
    let tile = on_card(&out, "tile", "onlyHere");
    let left = on_card(&out, "leftOff", "gui");
    assert_eq!((card.len(), tile.len(), left.len()), (1, 1, 1));
    // Over the card's population, even by repeating a branch it does hold.
    wants_refusal(copied(&[card[0].clone(), card[0].clone()]), "unsafe-name", "two handles on a card of one");
    // Two cards in one request, whichever they are.
    wants_refusal(copied(&[card[0].clone(), tile[0].clone()]), "unsafe-name", "a push card and the tile");
    wants_refusal(copied(&[card[0].clone(), left[0].clone()]), "unsafe-name", "a push card and a left-off card");
    // A Where-you-left-off request holds exactly one, whatever the population says.
    let mut roomy = left[0].clone().unwrap();
    roomy.population = 2;
    wants_refusal(copied(&[Some(roomy.clone()), Some(roomy)]), "unsafe-name", "two handles on a left-off card");
    // A held handle that is no copy target.
    wants_refusal(copied(&[Some(held(&out, "leftOff", "gui", "branch"))]), "unsafe-name", "a branch handle");
    let mut no_copy = held(&out, "leftOff", "gui", "branch");
    no_copy.population = 1;
    wants_refusal(copied(&[Some(no_copy)]), "unsafe-name", "a branch handle, the population aside");
    // An unknown handle has no card to compare: it skips those checks and refuses `stale`.
    wants_refusal(copied(&[None]), "stale", "unknown");
    wants_refusal(copied(&[card[0].clone(), None]), "unsafe-name", "still over the card's population of one");
    let names: Vec<Value> = vec![feature(Some(("origin", "feature"))), local_branch("solo", None, None)];
    let (reply, facts) = push_of(names);
    let out = minted(&reply, &facts);
    let two = on_card(&out, "push", CARD);
    // Two cards again, each with room for both: only the same-card rule can refuse this.
    let tile_of_two = on_card(&out, "tile", "onlyHere");
    assert_eq!((two[0].as_ref().unwrap().population, tile_of_two[0].as_ref().unwrap().population), (2, 2));
    wants_refusal(copied(&[two[0].clone(), tile_of_two[1].clone()]), "unsafe-name", "a push card and the tile, within both populations");
    wants_refusal(copied(&[two[0].clone(), None]), "stale", "one of two unknown");
    wants_refusal(copied(&[None, two[1].clone()]), "stale", "the other of two unknown");
    let (_, facts) = push_of(vec![local_branch("tag", None, None), feature(None)]);
    let refused = held_over(&["tag", "feature"], &facts);
    wants_refusal(copied(&[refused[0].clone(), None]), "stale", "stale is the first stage, and an unknown handle has no place in the card's order");
    // Repeats within the population are copied once, in card order.
    wants_copy(copied(&[two[1].clone(), two[0].clone()]),
        &format!("{REPO} -- 'origin' 'feature' && {REPO} -u -- 'origin' 'solo'"), "the card's order, not the request's");
    wants_copy(copied(&[two[1].clone(), two[1].clone()]), &format!("{REPO} -u -- 'origin' 'solo'"), "deduplicated");
}

#[test]
fn t9_thirty_two_handles_copy_and_thirty_three_refuse_untruncated() {
    let names = |n: usize| (0..n).map(|i| local_branch(&format!("b{i:02}"), None, None)).collect::<Vec<_>>();
    let (reply, facts) = push_of(names(32));
    let card = on_card(&minted(&reply, &facts), "push", CARD);
    assert_eq!(card.len(), 32);
    let (got, texts) = copied(&card);
    assert_eq!(got, json!({ "copied": true }));
    assert_eq!(texts[0].matches(" && ").count(), 31);
    // One more has no button at the mint, on the card or the tile, since only the cap would refuse it, at the click.
    let (reply, facts) = push_of(names(33));
    let out = minted(&reply, &facts);
    assert_eq!(on_card(&out, "push", CARD).len(), 0, "33 on the card");
    assert_eq!(on_card(&out, "tile", "onlyHere").len(), 0, "33 on the tile");
    let thirty_three: Vec<String> = (0..33).map(|i| format!("b{i:02}")).collect();
    wants_refusal(copied(&held_over(&thirty_three.iter().map(String::as_str).collect::<Vec<_>>(), &facts)), "unsafe-name", "33 of 33");
    // An over-limit list refuses before its handles matter.
    wants_refusal(copied(&vec![None; 33]), "unsafe-name", "33 unknown handles");
    wants_refusal(copied(&vec![None; 32]), "stale", "32 unknown handles");
}

/// Two push cards of `first` and `second` branches, in two repos and two stores, the second card's names starting `prefix`.
fn two_cards_of(first: usize, second: usize, prefix: &str) -> (Value, Value) {
    let named = |prefix: &str, n: usize| (0..n).map(|i| local_branch(&format!("{prefix}{i:02}"), None, None)).collect::<Vec<_>>();
    let (mut reply, mut facts) = push_of(named("a", first));
    let mut other = facts[0].clone();
    other["repoKey"] = json!("rsecond");
    other["path"] = json!("/fixture/b");
    other["branches"] = json!(named(prefix, second));
    facts.as_array_mut().unwrap().push(other);
    reply["repoViews"].as_array_mut().unwrap().push(json!({ "key": "rsecond", "name": "b", "state": "ok", "noRemote": false,
        "uncommitted": { "count": 0 }, "storeKey": "ssecond", "treeKey": "tsecond" }));
    let listed: Vec<Value> = (0..second).map(|i| json!({ "name": format!("{prefix}{i:02}"), "commits": 1 })).collect();
    reply["pushCards"].as_array_mut().unwrap().push(json!({ "repoKey": "rsecond", "storeKey": "ssecond", "firstLabel": null,
        "repoName": "b", "branches": listed, "onDefault": null }));
    (reply, facts)
}

/// The tile copies every card, so it can be over the list limit while no card is: it loses its button and they keep theirs.
#[test]
fn a_tile_over_the_list_limit_has_no_button_and_its_cards_keep_theirs() {
    let (reply, facts) = two_cards_of(17, 16, "b");
    let out = minted(&reply, &facts);
    assert_eq!(on_card(&out, "push", CARD).len(), 17);
    assert_eq!(on_card(&out, "push", "push:rsecond").len(), 16);
    assert_eq!(on_card(&out, "tile", "onlyHere").len(), 0, "33 across the cards");
    // At the limit it copies them all.
    let (reply, facts) = two_cards_of(16, 16, "b");
    let tile = on_card(&minted(&reply, &facts), "tile", "onlyHere");
    assert_eq!(tile.len(), 32);
    assert_eq!(copied(&tile).0, json!({ "copied": true }));
    // The same names in two stores are different branches, so they count twice.
    let (reply, facts) = two_cards_of(17, 16, "a");
    assert_eq!(on_card(&minted(&reply, &facts), "tile", "onlyHere").len(), 0, "33 in two stores, 17 names");
    // In one store they are the same branch, so they count once, as the tile lists them.
    let (mut reply, facts) = two_cards_of(32, 16, "a");
    reply["pushCards"][1]["storeKey"] = reply["pushCards"][0]["storeKey"].clone();
    let tile = on_card(&minted(&reply, &facts), "tile", "onlyHere");
    assert_eq!(tile.len(), 32, "48 entries, 32 branches");
    assert_eq!(copied(&tile).0, json!({ "copied": true }));
}

/// The limit counts branches, not list entries: the click sees each branch once, so a name listed twice is not one more.
#[test]
fn a_branch_listed_twice_counts_once_against_the_list_limit() {
    let names: Vec<Value> = (0..32).map(|i| local_branch(&format!("b{i:02}"), None, None)).collect();
    let (mut reply, facts) = push_of(names);
    reply["pushCards"][0]["onDefault"] = json!({ "name": "b00", "commits": 1 });
    let out = minted(&reply, &facts);
    let card = on_card(&out, "push", CARD);
    assert_eq!(card.len(), 32);
    assert_eq!(copied(&card).0, json!({ "copied": true }));
    assert_eq!(on_card(&out, "tile", "onlyHere").len(), 32);
}

/// The tile spans repos, by store and branch, in push-card order (B2 `:46`).
#[test]
fn t9_the_tile_copies_across_repos_and_refuses_whole() {
    let (mut reply, mut facts) = push_of(vec![feature(Some(("origin", "feature")))]);
    let mut second = facts[0].clone();
    second["repoKey"] = json!("rsecond");
    second["path"] = json!("/fixture/b");
    second["branches"] = json!([local_branch("b-work", None, None)]);
    facts.as_array_mut().unwrap().push(second);
    reply["repoViews"].as_array_mut().unwrap().push(json!({ "key": "rsecond", "name": "b", "state": "ok", "noRemote": false,
        "uncommitted": { "count": 0 }, "storeKey": "ssecond", "treeKey": "tsecond" }));
    reply["pushCards"].as_array_mut().unwrap().push(json!({ "repoKey": "rsecond", "storeKey": "ssecond", "firstLabel": null,
        "repoName": "b", "branches": [{ "name": "b-work", "commits": 1 }], "onDefault": null }));
    let out = minted(&reply, &facts);
    let tile = on_card(&out, "tile", "onlyHere");
    assert_eq!(tile.len(), 2, "both repos' branches");
    let joined = format!("{REPO} -- 'origin' 'feature' && git -C '/fixture/b' push -u -- 'origin' 'b-work'");
    wants_copy(copied(&tile), &joined, "the tile");
    let reversed: Vec<Option<HeldTarget>> = tile.iter().rev().cloned().collect();
    wants_copy(copied(&reversed), &joined, "the tile, requested backwards");
    // One branch of any repo refused since the mint refuses all of it, at the click.
    let (first, second) = (on_card(&out, "push", CARD), on_card(&out, "push", "push:rsecond"));
    facts[1]["remotes"][0]["transport"] = json!("refused");
    let mut gone_bad = tile.clone();
    let mut refused_repo = gone_bad[1].clone().unwrap();
    refused_repo.facts = std::sync::Arc::new(parse_action_facts(Some(facts.clone())).remove(1));
    gone_bad[1] = Some(refused_repo);
    wants_refusal(copied(&gone_bad), "transport", "the second repo's");
    // Each push card is still its own request, and may not join another's.
    wants_copy(copied(&first), &format!("{REPO} -- 'origin' 'feature'"), "the first card alone");
    wants_refusal(copied(&[first[0].clone(), second[0].clone()]), "unsafe-name", "two push cards");
    // At the mint that same refusal takes the button from its own card and from the tile, and from nothing else.
    let out = minted(&reply, &facts);
    assert_eq!(on_card(&out, "push", CARD).len(), 1, "the control: the other card keeps its button");
    assert_eq!(on_card(&out, "push", "push:rsecond").len(), 0);
    assert_eq!(on_card(&out, "tile", "onlyHere").len(), 0);
}

/// User decision 2026-11-05, on the push cards and the tile, as B2 `:42` has it for Where you left off: no button is shown
/// that could only refuse. The click is still judged in full, as a backstop.
#[test]
fn a_card_with_a_branch_that_refuses_has_no_copy_button_and_the_tile_copies_all_or_nothing() {
    // `app` lists a branch that copies and one that refuses, whichever comes first; `b` lists one that copies.
    let two_repos = |branches: Vec<Value>, on_default: Value| {
        let (mut reply, mut facts) = push_of(branches);
        reply["pushCards"][0]["onDefault"] = on_default;
        let mut second = facts[0].clone();
        second["repoKey"] = json!("rsecond");
        second["path"] = json!("/fixture/b");
        second["branches"] = json!([local_branch("b-work", None, None)]);
        facts.as_array_mut().unwrap().push(second);
        reply["repoViews"].as_array_mut().unwrap().push(json!({ "key": "rsecond", "name": "b", "state": "ok", "noRemote": false,
            "uncommitted": { "count": 0 }, "storeKey": "ssecond", "treeKey": "tsecond" }));
        reply["pushCards"].as_array_mut().unwrap().push(json!({ "repoKey": "rsecond", "storeKey": "ssecond", "firstLabel": null,
            "repoName": "b", "branches": [{ "name": "b-work", "commits": 1 }], "onDefault": null }));
        (reply, facts)
    };
    let counts = |out: &(Vec<ActionCard>, HeldTargets)| (on_card(out, "push", CARD).len(), on_card(out, "push", "push:rsecond").len(), on_card(out, "tile", "onlyHere").len());
    let good = || feature(Some(("origin", "feature")));
    let bad = || local_branch("tag", None, None);

    // The control: nothing refuses, so every button is there.
    let (reply, facts) = two_repos(vec![good(), local_branch("solo", None, None)], Value::Null);
    assert_eq!(counts(&minted(&reply, &facts)), (2, 1, 3));
    // One branch that refuses, on either side of one that copies, or as the card's default: that card and the tile go.
    for (branches, on_default) in [(vec![good(), bad()], Value::Null), (vec![bad(), good()], Value::Null)] {
        let (reply, facts) = two_repos(branches, on_default);
        let out = minted(&reply, &facts);
        assert_eq!(counts(&out), (0, 1, 0), "the other card keeps its button");
        wants_copy(copied(&on_card(&out, "push", "push:rsecond")), "git -C '/fixture/b' push -u -- 'origin' 'b-work'", "the other card still copies");
    }
    let (mut reply, facts) = two_repos(vec![good(), bad()], json!({ "name": "tag", "commits": 1 }));
    reply["pushCards"][0]["branches"] = json!([{ "name": "feature", "commits": 1 }]);
    assert_eq!(counts(&minted(&reply, &facts)), (0, 1, 0), "onDefault is a branch of the card");
    // The second card is the one refusing: the first keeps its button.
    let (reply, mut facts) = two_repos(vec![good()], Value::Null);
    facts[1]["remotes"][0]["push"] = json!(true);
    let out = minted(&reply, &facts);
    assert_eq!(counts(&out), (1, 0, 0));
    wants_copy(copied(&on_card(&out, "push", CARD)), &format!("{REPO} -- 'origin' 'feature'"), "the first card still copies");
    // A card listing no branch has nothing to refuse, so it costs nothing.
    let (mut reply, facts) = two_repos(vec![good()], Value::Null);
    reply["pushCards"][1]["branches"] = json!([]);
    assert_eq!(counts(&minted(&reply, &facts)), (1, 0, 1));
    // Mint first, with facts that copy; a refusal arriving after that still answers at the click, with its own code.
    let (reply, mut facts) = two_repos(vec![good()], Value::Null);
    let out = minted(&reply, &facts);
    let (card, tile) = (on_card(&out, "push", CARD), on_card(&out, "tile", "onlyHere"));
    facts[0]["remotes"][0]["transport"] = json!("refused");
    let later = |h: &Option<HeldTarget>| {
        let mut h = h.clone().unwrap();
        h.facts = std::sync::Arc::new(parse_action_facts(Some(facts.clone())).remove(0));
        Some(h)
    };
    wants_refusal(copied(&[later(&card[0])]), "transport", "the card");
    wants_refusal(copied(&[later(&tile[0]), tile[1].clone()]), "transport", "the tile");
}

/// B2 `:42`: the button is shown only when a private push target is eligible. A push card's branch has the same rule, with
/// its whole card: see the test above.
#[test]
fn t9_where_you_left_off_shows_copy_only_on_an_eligible_branch() {
    let (reply, facts) = fx();
    assert!(left_off(&reply, &facts).contains(&"copy".to_string()), "the control: an eligible branch");
    let cases: [(&str, fn(&mut Value)); 9] = [
        ("an http:// remote", |f: &mut Value| f["remotes"][0]["transport"] = json!("refused")),
        ("a set vcs", |f: &mut Value| f["remotes"][0]["vcs"] = json!(true)),
        ("a refspec", |f: &mut Value| f["remotes"][0]["push"] = json!(true)),
        ("a legacy entry", |f: &mut Value| { f["remotes"][0]["legacy"] = json!(true); f["legacyNames"] = json!(["origin"]); }),
        ("a . remote", |f: &mut Value| f["branches"][0]["pushRemote"] = json!(".")),
        ("no url", |f: &mut Value| f["remotes"][0]["url"] = json!(false)),
        ("a differently named upstream that is its destination", |f: &mut Value| { f["pushesToUpstream"] = json!(true); f["branches"][0]["upstreamBranch"] = json!("elsewhere"); }),
        ("a failed ref-format check", |f: &mut Value| f["branches"][0]["refFormatOk"] = json!(false)),
        ("an unsafe repo path", |f: &mut Value| f["path"] = json!("/fixture/[redacted]")),
    ];
    for (why, bend) in cases {
        let mut bent = facts.clone();
        bend(&mut bent[0]);
        let out = minted(&reply, &bent);
        assert!(!shape(&out.0, "leftOff", "gui").contains(&"copy".to_string()), "{why}");
        assert_eq!(shape(&out.0, "push", CARD), Vec::<String>::new(), "{why}: nor on the push card that lists it");
        assert_eq!(shape(&out.0, "tile", "onlyHere"), Vec::<String>::new(), "{why}: nor on the tile");
    }
}

