/* ── The clicks on a live state: a fixture reply through `repos::status`, then the sink's own entry point ───────────── */

#[cfg(unix)]
mod live_clicks {
    use super::*;
    use daily_briefing_gui_lib::actions::{copy_handles, open_handle};
    use daily_briefing_gui_lib::editor::{open_folder, EditorOpenRequest};
    use daily_briefing_gui_lib::engine::EngineClient;
    use daily_briefing_gui_lib::live_gate::{LiveEnv, Visibility};
    use daily_briefing_gui_lib::repos::{status, ReposIpcRequest, ReposLive};
    use daily_briefing_gui_lib::schedule_state::Now;
    use std::path::PathBuf;
    use std::sync::Arc;

    pub struct Rig {
        _scratch: common::ScratchDir,
        pub root: PathBuf,
        pub client: EngineClient,
        pub env: LiveEnv,
        pub live: ReposLive,
    }

    impl Rig {
        /// An engine that answers the fixture's reply, with its facts materialised under a scratch root.
        pub fn new(tag: &str) -> Self {
            let scratch = common::ScratchDir::new(tag);
            let root = std::fs::canonicalize(&scratch.path).expect("the root");
            let fx = vectors();
            let mut doc = fx["reply"].clone();
            doc["repos"] = json!([]);
            doc["actionFacts"] = common::materialise_action_facts(&root, &fx["actionFacts"]);
            std::fs::write(scratch.join("all.json"), doc.to_string()).expect("all.json");
            let body = format!("cat > /dev/null\ncat {}", common::sq(&scratch.join("all.json").display().to_string()));
            let program = common::fake_sidecar(&scratch.path, "engine.sh", &body);
            let env = LiveEnv::default()
                .with_visibility(Arc::new(|| Visibility { visible: true, minimized: false }))
                .with_clock(Arc::new(|| Now { local_date: "2026-01-11".into(), minutes: 600, epoch_secs: 1_000 }));
            Rig { _scratch: scratch, root, client: EngineClient::with_program(program), env, live: ReposLive::default() }
        }

        /// One full check: the reply as it crosses.
        pub async fn ask(&self) -> Value {
            let request: ReposIpcRequest = serde_json::from_value(json!({
                "labels": [{ "key": "repo", "tokens": [] }, { "key": "gui", "tokens": ["5fab0a2"] }],
                "branches": [{ "key": "gui", "name": "feature/contract" }],
                "pageDate": "2026-01-11",
                "reason": "first",
                "current": "whatYouDid",
            })).expect("a well-formed ask");
            let visible = || Visibility { visible: true, minimized: false };
            status(&self.client, &self.env, visible, &self.live, request).await.expect("the check").0
        }

        /// The handle of `target` on a card of the crossing reply.
        pub fn handle(reply: &Value, kind: &str, target: &str) -> String {
            reply["actions"].as_array().expect("actions").iter().filter(|c| c["cardKind"] == kind)
                .flat_map(|c| c["handles"].as_array().expect("handles")).find(|h| h["target"] == target)
                .unwrap_or_else(|| panic!("no {target} on {kind}: {reply}"))["handle"].as_str().expect("a handle").to_string()
        }

        pub async fn open(&self, handle: &str, on: bool) -> (Value, Vec<String>) {
            let request: OpenGithubRequest = serde_json::from_value(json!({ "handle": handle })).expect("a request");
            let opener = common::RecordingOpener::default();
            let reply = open_handle(&self.live, request, on, &opener).await;
            (serde_json::to_value(&reply).expect("a reply"), opener.urls())
        }

        pub async fn copy(&self, handles: &[String]) -> (Value, Vec<String>) {
            let request: CopyPushRequest = serde_json::from_value(json!({ "handles": handles })).expect("a request");
            let clipboard = RecordingClipboard::default();
            let reply = copy_handles(&self.live, request, &clipboard).await;
            (serde_json::to_value(&reply).expect("a reply"), clipboard.texts())
        }
    }

    /// Editor stage (T11, plan P-M3): one fixture-minted editor handle with a stored choice reaches the recording launcher
    /// with exactly the fixture's rebased argv. The installed bundle is the literal's own, so the two cannot disagree by a
    /// default. The fixture's facts say which branch the checkout holds; `HEAD` is what the launch reads.
    #[tokio::test(flavor = "multi_thread")]
    async fn t11_a_crossing_editor_handle_launches_the_fixtures_argv() {
        let rig = Rig::new("t11live");
        std::fs::write(rig.root.join("repo/.git/HEAD"), "ref: refs/heads/feature/contract\n").expect("HEAD");
        let reply = rig.ask().await;
        let handle = Rig::handle(&reply, "leftOff", "editor");
        let shown = reply["actions"].as_array().unwrap().iter().flat_map(|c| c["handles"].as_array().unwrap())
            .find(|h| h["handle"] == handle.as_str()).expect("the handle");
        let store = rig.root.join("app-data");
        let project = ProjectKey::parse(shown["project"].as_str().expect("an editor handle's project")).expect("a project key");
        AppPrefs::default().set_editor_choice(&store, project.clone(), EditorChoice::Editor(EditorId::VsCode)).expect("the choice");
        let stored = serde_json::to_value(read_prefs(&store).editor_choices[&project]).expect("a token");
        let fx = vectors();
        let launcher = RecordingLauncher::default();
        let bundle = fx["expectedSinks"]["editor"][0][2].as_str().expect("the literal's bundle").to_string();
        let request: EditorOpenRequest = serde_json::from_value(json!({ "handle": handle, "editor": stored })).expect("a request");
        let replied = open_folder(&rig.live, true, &OnlyBundle(bundle), &launcher, request).await;
        assert_eq!(serde_json::to_value(&replied).unwrap(), json!({ "opened": true }));
        let want: Value = serde_json::from_str(&fx["expectedSinks"]["editor"].to_string().replace("/fixture", rig.root.to_str().unwrap())).unwrap();
        assert_eq!(json!(*launcher.argv.lock().unwrap()), want, "the recording launcher got exactly the fixture's argv");
    }

    #[tokio::test(flavor = "multi_thread")]
    async fn t8_a_crossing_handle_opens_through_the_commands_own_path() {
        let rig = Rig::new("t8live");
        let reply = rig.ask().await;
        let handle = Rig::handle(&reply, "did", "pr");
        let fx = vectors();
        let (replied, urls) = rig.open(&handle, true).await;
        assert_eq!(replied, json!({ "opened": true }));
        assert_eq!(json!(urls), fx["expectedSinks"]["open"]);
        assert!(!urls[0].contains(rig.root.to_str().unwrap()));
        assert!(rig.live.holds_handle(&handle), "a click does not spend the handle");
        // The switch off, an editor handle and a handle Rust never minted reach no sink either.
        assert_eq!(rig.open(&handle, false).await, (json!({ "refused": "links-off" }), vec![]));
        let editor = Rig::handle(&reply, "leftOff", "editor");
        assert_eq!(rig.open(&editor, true).await, (json!({ "refused": "invalid-target" }), vec![]));
        assert_eq!(rig.open("0000.0.0000", true).await, (json!({ "refused": "stale" }), vec![]));
    }

    /// R2-O3: a source that changed since the check is found by THIS click: it clears every old handle and the next
    /// reply, refuses `stale`, and never reaches the opener. A click that resolved first and checked second would open.
    #[tokio::test(flavor = "multi_thread")]
    async fn t8_a_changed_source_is_checked_before_the_handle_resolves() {
        let rig = Rig::new("t8chg");
        let reply = rig.ask().await;
        let handle = Rig::handle(&reply, "did", "pr");
        let other = Rig::handle(&reply, "leftOff", "branch");
        std::fs::write(rig.root.join("repo/.git/config"), "[remote \"origin\"]\n\turl = https://github.com/else/where.git\n").expect("the config");
        assert!(rig.live.holds_handle(&handle), "nothing has looked yet");
        assert_eq!(rig.open(&handle, true).await, (json!({ "refused": "stale" }), vec![]));
        assert!(!rig.live.holds_handle(&handle) && !rig.live.holds_handle(&other), "every old handle went with it");
    }

    #[tokio::test(flavor = "multi_thread")]
    async fn t9_a_crossing_handle_copies_through_the_commands_own_path() {
        let rig = Rig::new("t9live");
        let reply = rig.ask().await;
        let handle = Rig::handle(&reply, "push", "copy");
        let root = rig.root.to_str().unwrap();
        let want: Vec<String> = vectors()["expectedSinks"]["copy"].as_array().unwrap().iter()
            .map(|c| c.as_str().unwrap().replace("/fixture", root)).collect();
        assert_eq!(rig.copy(std::slice::from_ref(&handle)).await, (json!({ "copied": true }), want.clone()));
        assert_eq!(rig.copy(&[Rig::handle(&reply, "tile", "copy")]).await, (json!({ "copied": true }), want.clone()));
        assert_eq!(rig.copy(&[Rig::handle(&reply, "leftOff", "copy")]).await, (json!({ "copied": true }), want));
        assert_eq!(rig.copy(&[]).await, (json!({ "refused": "unsafe-name" }), vec![]));
        assert_eq!(rig.copy(&["0000.0.0000".to_string()]).await, (json!({ "refused": "stale" }), vec![]));
        assert!(rig.live.holds_handle(&handle), "a copy does not spend the handle");
    }

    /// R2-O3, as for `open_github`. A legacy file appearing is one such source (B2 `:31`, `:125`).
    #[tokio::test(flavor = "multi_thread")]
    async fn t9_a_changed_source_is_checked_before_any_handle_resolves() {
        for change in ["a config edit", "a legacy folder and entry appearing", "a legacy entry appearing in an existing folder"] {
            let rig = Rig::new("t9chg");
            let reply = rig.ask().await;
            let handle = Rig::handle(&reply, "push", "copy");
            let git = rig.root.join("repo/.git");
            match change {
                "a config edit" => std::fs::write(git.join("config"), "[remote \"origin\"]\n\tpush = x\n").expect("the config"),
                "a legacy folder and entry appearing" => {
                    std::fs::create_dir_all(git.join("remotes")).expect("the legacy folder");
                    std::fs::write(git.join("remotes/origin"), "URL: https://host/repo\n").expect("the legacy entry");
                }
                // The fixture stamps `branches` as an existing folder and `remotes` as missing.
                _ => {
                    assert!(git.join("branches").is_dir(), "the folder is already there");
                    std::fs::write(git.join("branches/origin"), "https://host/repo\n").expect("the legacy entry");
                }
            }
            assert!(rig.live.holds_handle(&handle), "{change}: nothing has looked yet");
            assert_eq!(rig.copy(std::slice::from_ref(&handle)).await, (json!({ "refused": "stale" }), vec![]), "{change}");
            assert!(!rig.live.holds_handle(&handle), "{change}: the old handles went with it");
        }
    }

    /// An over-limit list is refused before anything is sampled or resolved. The changed source is what shows it: a sample
    /// would find the edit and clear the handle, so a handle still held means nothing looked.
    #[tokio::test(flavor = "multi_thread")]
    async fn t9_an_over_limit_request_refuses_before_any_sample() {
        let rig = Rig::new("t9cap");
        let reply = rig.ask().await;
        let handle = Rig::handle(&reply, "push", "copy");
        std::fs::write(rig.root.join("repo/.git/config"), "[remote \"origin\"]\n\tpush = x\n").expect("the config");
        assert_eq!(rig.copy(&vec![handle.clone(); 33]).await, (json!({ "refused": "unsafe-name" }), vec![]));
        assert!(rig.live.holds_handle(&handle), "the long list must not have sampled the sources");
        // The control: the same edit does clear it for a list that gets as far as the sample.
        assert_eq!(rig.copy(std::slice::from_ref(&handle)).await, (json!({ "refused": "stale" }), vec![]));
        assert!(!rig.live.holds_handle(&handle));
    }
}

