const COUNTERPARTS: &str = include_str!("fixtures/upstream-counterpart-vectors.json");

/// What the first handle of `target` on the card opens, or `None` with no such handle.
fn opened_by(out: &(Vec<ActionCard>, HeldTargets), kind: &str, id: &str, target: &str) -> Option<String> {
    let handle = out.0.iter().filter(|c| c.card_kind.as_str() == kind && c.card_id == id)
        .flat_map(|c| &c.handles).find(|h| h.target.as_str() == target)?;
    let (reply, urls) = click(Some(&out.1[&handle.handle]), true);
    assert_eq!(reply, json!({ "opened": true }), "{target} on {kind} {id}");
    urls.first().cloned()
}

/// The flows real git built (`test/repos.reach.test.ts`, the same file): `git checkout -b feat origin/develop` takes
/// that branch as its upstream, and that is where it started, not where it pushes (B2 `:38`, plan §0).
#[test]
fn round4_a_differently_named_upstream_counts_only_where_git_would_really_push_there() {
    let v: Value = serde_json::from_str(COUNTERPARTS).expect("the fixture is JSON");
    let cases = v["cases"].as_object().expect("cases");
    assert_eq!(cases.len(), 34);
    for (name, case) in cases {
        let (mut reply, mut facts) = fx();
        let f = &case["facts"];
        with_rows(&mut reply, json!([{ "kind": "branch", "name": "feat", "push": null, "commits": [commit(PUSHED)] }]));
        reply["branchLines"] = json!([{ "key": "gui", "name": "feat", "state": "live", "notPushed": 1, "neverPushed": false, "behind": 0 }]);
        facts[0]["pushDefault"] = f["pushDefault"].clone();
        facts[0]["pushesToUpstream"] = f["pushesToUpstream"].clone();
        facts[0]["remotes"] = f["remotes"].as_array().unwrap().iter().map(|r| {
            let mut entry = remote_entry(r["name"].as_str().unwrap(), r["owner"].as_str().unwrap());
            entry["defaultBranch"] = r["defaultBranch"].clone();
            entry
        }).collect();
        let mut branch = f["branch"].clone();
        for (k, x) in [("remoteFactsUnknown", json!(false)), ("checkoutPath", Value::Null), ("refFormatOk", json!(true)), ("tip", json!(OTHER)), ("name", json!("feat"))] {
            branch[k] = x;
        }
        facts[0]["branches"] = json!([branch]);
        facts[0]["remoteBranches"] = f["remoteBranches"].as_array().unwrap().iter().map(|e| {
            json!({ "remote": e["remote"], "name": e["name"], "sha": if e["atTip"] == json!(true) { OTHER } else { MAIN_TIP } })
        }).collect();
        let expect = &case["expect"];
        let want = |k: &str| expect[k].as_str().map(str::to_string);
        let out = minted(&reply, &facts);
        assert_eq!(opened_by(&out, "did", "gui", "branch"), want("branch"), "{name}: the row");
        assert_eq!(opened_by(&out, "leftOff", "gui", "branch"), want("branch"), "{name}: the card");
        assert_eq!(opened_by(&out, "leftOff", "gui", "compare"), want("compare"), "{name}: Compare");
        // The copied command: a real destination of another name refuses before any text (B2 `:94`); anything else names
        // the branch's own name, with no -u, so the upstream stays (plan §0).
        let parsed = parse_action_facts(Some(facts.clone()));
        let judged = judge_copy_branch(&parsed[0], "feat");
        let copy = judged.as_ref().err().map(|r| serde_json::to_value(r).unwrap()).unwrap_or(Value::Null);
        assert_eq!(copy, expect["copy"], "{name}: copy");
        assert_eq!(judged.ok().map(|c| c.text()), want("command").map(|c| format!("{REPO} {c}")), "{name}: the copied text");
        assert_eq!(shape(&out.0, "leftOff", "gui").iter().any(|w| w == "copy"), expect["copy"].is_null(), "{name}: the Copy button");
    }
}

/// B2 `:82`: one refused branch refuses the whole push card and the tile, so with one remote a branch made from `origin/main`
/// must not.
#[test]
fn round4_with_one_remote_a_branch_made_from_the_default_keeps_the_push_card_and_tile_copying() {
    let branches = || vec![local_branch("started", Some(("origin", "main")), Some(OTHER)), feature(Some(("origin", "feature")))];
    let (reply, facts) = push_of(branches());
    let out = minted(&reply, &facts);
    let want = format!("{REPO} -- 'origin' 'started' && {REPO} -- 'origin' 'feature'");
    wants_copy(copied(&on_card(&out, "push", CARD)), &want, "the push card");
    wants_copy(copied(&on_card(&out, "tile", "onlyHere")), &want, "the tile");
    // Under `push.default=upstream` the same upstream is its real destination, and that refuses both.
    let (reply, mut facts) = push_of(branches());
    facts[0]["pushesToUpstream"] = json!(true);
    let out = minted(&reply, &facts);
    assert_eq!((on_card(&out, "push", CARD).len(), on_card(&out, "tile", "onlyHere").len()), (0, 0), "no button that could only refuse");
    let clean = minted(&reply, &push_of(branches()).1);
    let later = |handles: Vec<Option<HeldTarget>>| handles.iter().map(|h| Some(over(h.as_ref().unwrap(), &facts))).collect::<Vec<_>>();
    wants_refusal(copied(&later(on_card(&clean, "push", CARD))), "name-mismatch", "the push card");
    wants_refusal(copied(&later(on_card(&clean, "tile", "onlyHere"))), "name-mismatch", "the tile");
}

/// One repo's card over the branches `started` and `feature`, beside a second repository's own card. `bend` is the first
/// repo's remotes, put on after the clone so the second repository has its one remote.
fn started_beside_a_second_repo(started: Value, beside: Value, bend: impl FnOnce(&mut Value)) -> (Value, Value) {
    let (mut reply, mut facts) = push_of(vec![started, beside]);
    let mut second = facts[0].clone();
    second["repoKey"] = json!("rsecond");
    second["path"] = json!("/fixture/b");
    second["branches"] = json!([local_branch("b-work", None, None)]);
    facts.as_array_mut().unwrap().push(second);
    bend(&mut facts[0]);
    reply["repoViews"].as_array_mut().unwrap().push(json!({ "key": "rsecond", "name": "b", "state": "ok", "noRemote": false,
        "uncommitted": { "count": 0 }, "storeKey": "ssecond", "treeKey": "tsecond" }));
    reply["pushCards"].as_array_mut().unwrap().push(json!({ "repoKey": "rsecond", "storeKey": "ssecond", "firstLabel": null,
        "repoName": "b", "branches": [{ "name": "b-work", "commits": 1 }], "onDefault": null }));
    (reply, facts)
}

/// Beside a second remote, nothing selects one for a branch made from a default, so `origin` does (user decision 2026-11-05),
/// for all of the push card and all of the tile, and the reply says so, even with a branch beside it that needed no such
/// rule. A second repository's own card does not, having one remote. Real git's flow is the fixture's "fork, upstream/main
/// with no selection, never pushed".
#[test]
fn round4_beside_a_second_remote_a_branch_made_from_the_default_copies_to_origin_on_the_push_card_and_tile() {
    for start in ["origin", "upstream"] {
        let started = local_branch("started", Some((start, "main")), Some(OTHER));
        let (mut reply, facts) = started_beside_a_second_repo(started, feature(Some(("origin", "feature"))), beside_upstream);
        let out = minted(&reply, &facts);
        let (card, tile) = (on_card(&out, "push", CARD), on_card(&out, "tile", "onlyHere"));
        assert_eq!((card.len(), tile.len()), (2, 3), "started from {start}: every branch keeps its handle");
        let both = format!("{REPO} -- 'origin' 'started' && {REPO} -- 'origin' 'feature'");
        let beside = format!("{REPO} -- 'origin' 'feature'");
        let elsewhere = "git -C '/fixture/b' push -u -- 'origin' 'b-work'";
        wants_origin_copy(copied(&card), &both, "the push card");
        wants_origin_copy(copied(&tile), &format!("{both} && {elsewhere}"), "the tile, the second repository beside it");
        // The controls: the commands no such rule chose read as a plain copy, alone or together.
        wants_copy(copied(&card[1..]), &beside, "the branch beside it, alone");
        wants_copy(copied(&on_card(&out, "push", "push:rsecond")), elsewhere, "the second repository's own card");
        wants_copy(copied(&tile[1..]), &format!("{beside} && {elsewhere}"), "the tile without that handle");
        // The second repository first on the tile, so that branch is judged last.
        reply["pushCards"].as_array_mut().unwrap().reverse();
        let out = minted(&reply, &facts);
        let tile = on_card(&out, "tile", "onlyHere");
        assert_eq!(tile.len(), 3);
        wants_origin_copy(copied(&tile), &format!("{elsewhere} && {both}"), "the tile, that repository second");
    }
}

/// Neither remote is `origin`, so nothing selects one for that branch: it refuses, so that card and the tile have no button,
/// though the branch beside it (its upstream is its real destination) and the second repository could each copy alone.
#[test]
fn beside_a_second_remote_with_no_origin_a_branch_made_from_the_default_hides_the_card_and_tile() {
    let started = local_branch("started", Some(("upstream", "main")), Some(OTHER));
    let beside = feature(Some(("fork", "feature")));
    let (reply, facts) = started_beside_a_second_repo(started.clone(), beside.clone(), no_origin);
    let out = minted(&reply, &facts);
    assert_eq!((on_card(&out, "push", CARD).len(), on_card(&out, "tile", "onlyHere").len()), (0, 0), "that card and the tile");
    wants_copy(copied(&on_card(&out, "push", "push:rsecond")), "git -C '/fixture/b' push -u -- 'origin' 'b-work'", "the control: the other card keeps its button");
    // At the click: only that branch refuses.
    wants_refusal(copy_bent(vec![started.clone(), beside.clone()], no_origin), "ambiguous", "the whole card");
    wants_refusal(copy_bent(vec![started], no_origin), "ambiguous", "that branch alone");
    wants_copy(copy_bent(vec![beside], no_origin), &format!("{REPO} -- 'fork' 'feature'"), "the branch beside it, alone");
}

/// User decision 2026-11-05: `pushRemote`, `pushDefault` and a real-destination upstream still win, in that order, and only
/// when none of them selects does `origin` among several remotes get the copy. Literal bytes, on purpose.
#[test]
fn among_several_remotes_origin_is_the_last_arm_and_the_reply_says_when_it_was_used() {
    // The user's case: `git checkout -b feature upstream/main`, with remotes `origin` and `upstream`.
    wants_origin_copy(copy_bent(vec![feature(Some(("upstream", "main")))], beside_upstream),
        "git -C '/fixture/repo' push -- 'origin' 'feature'", "started from upstream/main: no -u, so the upstream stays");
    wants_origin_copy(copy_bent(vec![feature(None)], beside_upstream),
        "git -C '/fixture/repo' push -u -- 'origin' 'feature'", "no upstream: -u");
    wants_origin_copy(copy_bent(vec![feature(None)], |f| {
        beside_upstream(f);
        f["remotes"].as_array_mut().unwrap().push(remote_entry("third", "third-org"));
    }), "git -C '/fixture/repo' push -u -- 'origin' 'feature'", "three remotes");

    // Selected by something else, beside `origin`: that remote, and a plain copy.
    let mut named = feature(Some(("origin", "main")));
    named["pushRemote"] = json!("upstream");
    wants_copy(copy_bent(vec![named], beside_upstream), "git -C '/fixture/repo' push -- 'upstream' 'feature'", "pushRemote names another");
    wants_copy(copy_bent(vec![feature(None)], |f| { beside_upstream(f); f["pushDefault"] = json!("upstream"); }),
        "git -C '/fixture/repo' push -u -- 'upstream' 'feature'", "pushDefault names another");
    wants_copy(copy_bent(vec![feature(Some(("upstream", "feature")))], beside_upstream),
        "git -C '/fixture/repo' push -- 'upstream' 'feature'", "an upstream of its own name, on another remote, is its real destination");
    let mut both = feature(None);
    both["pushRemote"] = json!("upstream");
    wants_copy(copy_bent(vec![both], |f| { beside_upstream(f); f["pushDefault"] = json!("origin"); }),
        "git -C '/fixture/repo' push -u -- 'upstream' 'feature'", "pushRemote before pushDefault");
    // `origin` by selection or as the only remote is no guess, so it says nothing.
    wants_copy(copy_bent(vec![feature(None)], |f| { beside_upstream(f); f["pushDefault"] = json!("origin"); }),
        "git -C '/fixture/repo' push -u -- 'origin' 'feature'", "pushDefault names origin");
    let mut own = feature(None);
    own["pushRemote"] = json!("origin");
    wants_copy(copy_bent(vec![own], beside_upstream), "git -C '/fixture/repo' push -u -- 'origin' 'feature'", "pushRemote names origin");
    wants_copy(copy_bent(vec![feature(Some(("origin", "feature")))], beside_upstream),
        "git -C '/fixture/repo' push -- 'origin' 'feature'", "origin as the real destination");
    wants_copy(copy_bent(vec![feature(None)], |_| {}), "git -C '/fixture/repo' push -u -- 'origin' 'feature'", "origin as the sole remote");

    // One command by this arm is enough, in a copy holding others.
    let mut elsewhere = local_branch("elsewhere", None, Some(OTHER));
    elsewhere["pushRemote"] = json!("upstream");
    wants_origin_copy(copy_bent(vec![elsewhere, feature(None)], beside_upstream),
        "git -C '/fixture/repo' push -u -- 'upstream' 'elsewhere' && git -C '/fixture/repo' push -u -- 'origin' 'feature'", "one of two");
}

/// Selecting `origin` settles only the name. What follows selection reads it as it reads any other, and what cannot be
/// counted stays uncounted.
#[test]
fn origin_among_several_remotes_is_judged_like_any_selected_remote() {
    let two = beside_upstream;
    let started = || feature(Some(("upstream", "main")));
    wants_refusal(copy_bent(vec![started()], |f| { two(f); f["remotes"][0]["push"] = json!(true); }), "name-mismatch", "a push refspec");
    wants_refusal(copy_bent(vec![started()], |f| { two(f); f["remotes"][0]["legacy"] = json!(true); f["legacyNames"] = json!(["origin"]); }), "name-mismatch", "a legacy entry");
    wants_refusal(copy_bent(vec![started()], |f| {
        two(f);
        f["remotes"][0]["configSection"] = json!(false);
        f["remotes"][0]["url"] = json!(false);
        f["remotes"][0]["legacy"] = json!(true);
        f["legacyNames"] = json!(["origin"]);
    }), "name-mismatch", "a legacy-only origin is still a name among the remotes, and still refused");
    wants_refusal(copy_bent(vec![started()], |f| { two(f); f["remotes"][0]["transport"] = json!("refused"); }), "transport", "an http:// destination");
    wants_refusal(copy_bent(vec![started()], |f| { two(f); f["remotes"][0]["vcs"] = json!(true); }), "transport", "a vcs setting");
    wants_refusal(copy_bent(vec![started()], |f| { two(f); f["remotes"][0]["url"] = json!(false); }), "no-remote", "a section with no url");
    wants_refusal(copy_bent(vec![started()], |f| { two(f); f["remotes"][0]["push"] = Value::Null; }), "ambiguous", "its refspec unknown");
    wants_refusal(copy_bent(vec![started()], |f| { two(f); f["remotes"][1]["legacy"] = json!(true); f["legacyNames"] = json!(["upstream"]); }), "name-mismatch", "a legacy start point");
    wants_refusal(copy_bent(vec![feature(Some(("upstream", "other")))], |f| { two(f); f["pushesToUpstream"] = json!(true); }), "name-mismatch", "the upstream is the destination, so the arm is never reached");
    wants_refusal(copy_bent(vec![feature(Some((".", "main")))], two), "no-remote", "a . upstream is never reached either");

    // What makes the names unknown keeps `origin` from being read out of them.
    wants_refusal(copy_bent(vec![feature(None)], |f| { two(f); f["omittedRemotes"] = json!(true); }), "ambiguous", "a left-out name");
    wants_refusal(copy_bent(vec![feature(None)], |f| { two(f); f["legacyNames"] = Value::Null; }), "ambiguous", "the legacy list unknown");
    wants_refusal(copy_bent(vec![feature(None)], |f| { two(f); f["remotes"][1]["configSection"] = Value::Null; }), "ambiguous", "another remote's section unknown");
    wants_refusal(copy_bent(vec![feature(None)], |f| { two(f); f["remotes"][0]["configSection"] = Value::Null; }), "ambiguous", "origin's section unknown");

    // `origin` has to be one of the known names, exactly.
    let absent = json!({ "name": "origin", "transport": null, "github": null, "vcs": false, "push": false,
        "configSection": false, "url": false, "legacy": false, "defaultBranch": null });
    wants_refusal(copy_bent(vec![feature(None)], |f| {
        no_origin(f);
        f["remotes"].as_array_mut().unwrap().push(absent);
    }), "ambiguous", "listed, with nothing behind the name");
    wants_refusal(copy_bent(vec![feature(None)], |f| {
        f["remotes"] = json!([remote_entry("Origin", "org"), remote_entry("upstream", "up-org")]);
    }), "ambiguous", "another name, by case");
    wants_refusal(copy_bent(vec![feature(None)], |f| {
        no_origin(f);
        f["legacyNames"] = json!(["origin"]);
    }), "ambiguous", "a legacy origin the remotes do not list has no facts to go on");
}

/// The rule's every clause, on facts git would not always leave: another remote selected by either setting, or the same one.
#[test]
fn round4_only_a_selection_of_another_remote_takes_the_destination_away() {
    let with_fork = |f: &mut Value| {
        f["pushesToUpstream"] = json!(true);
        f["remotes"].as_array_mut().unwrap().push(remote_entry("fork", "fork-org"));
    };
    let to = |push: Option<&str>| {
        let mut b = feature(Some(("origin", "other")));
        b["pushRemote"] = json!(push);
        b
    };
    wants_refusal(copy_bent(vec![to(None)], with_fork), "name-mismatch", "no selection");
    wants_refusal(copy_bent(vec![to(Some("origin"))], with_fork), "name-mismatch", "pushRemote is the upstream's remote");
    wants_refusal(copy_bent(vec![to(None)], |f| { with_fork(f); f["pushDefault"] = json!("origin"); }), "name-mismatch", "pushDefault is the upstream's remote");
    wants_refusal(copy_bent(vec![to(Some("origin"))], |f| { with_fork(f); f["pushDefault"] = json!("fork"); }), "name-mismatch", "pushRemote beats pushDefault");
    let elsewhere = format!("{REPO} -- 'fork' 'feature'");
    wants_copy(copy_bent(vec![to(Some("fork"))], with_fork), &elsewhere, "pushRemote selects another");
    wants_copy(copy_bent(vec![to(None)], |f| { with_fork(f); f["pushDefault"] = json!("fork"); }), &elsewhere, "pushDefault selects another");
    wants_copy(copy_bent(vec![to(Some("fork"))], |f| { with_fork(f); f["pushDefault"] = json!("origin"); }), &elsewhere, "pushRemote beats pushDefault, the other way");
    // Git's own default: no destination whatever else is set, so it selects nothing among two remotes, and `origin` gets it.
    wants_origin_copy(copy_bent(vec![to(None)], |f| f["remotes"].as_array_mut().unwrap().push(remote_entry("fork", "fork-org"))),
        &format!("{REPO} -- 'origin' 'feature'"), "the setting off");
    wants_refusal(copy_bent(vec![feature(Some(("fork", "other")))], no_origin), "ambiguous", "the setting off, and neither remote is origin");
}

/// `git checkout -b feat upstream/main` leaves `upstream` only as where the branch started, and plain `git push` refuses
/// there (measured with real git), so it must not pick the copied text's remote: among several remotes that is `origin`, or
/// no remote (user decision 2026-11-05). Literal bytes, on purpose.
#[test]
fn post_cap_an_upstream_that_is_only_a_start_point_selects_no_remote() {
    let two = |f: &mut Value| f["remotes"].as_array_mut().unwrap().push(remote_entry("upstream", "up-org"));
    wants_origin_copy(copy_bent(vec![feature(Some(("upstream", "main")))], two),
        "git -C '/fixture/repo' push -- 'origin' 'feature'", "two remotes, started from upstream/main: origin, not the start point");
    wants_origin_copy(copy_bent(vec![feature(Some(("origin", "main")))], two),
        "git -C '/fixture/repo' push -- 'origin' 'feature'", "two remotes, started from origin/main: the new rule, not the start point");
    wants_refusal(copy_bent(vec![feature(Some(("upstream", "main")))], no_origin), "ambiguous", "two remotes, no origin, started from upstream/main: the start point still selects nothing");
    wants_refusal(copy_bent(vec![feature(Some(("fork", "main")))], no_origin), "ambiguous", "two remotes, no origin, started from fork/main");
    wants_copy(copy_bent(vec![feature(Some(("origin", "develop")))], |_| {}),
        "git -C '/fixture/repo' push -- 'origin' 'feature'", "one remote, started from origin/develop: no -u");
    wants_copy(copy_bent(vec![feature(Some(("upstream", "main")))], |f| { two(f); f["pushDefault"] = json!("origin"); }),
        "git -C '/fixture/repo' push -- 'origin' 'feature'", "pushDefault still selects");
    let mut pushes = feature(Some(("upstream", "main")));
    pushes["pushRemote"] = json!("origin");
    wants_copy(copy_bent(vec![pushes], two), "git -C '/fixture/repo' push -- 'origin' 'feature'", "pushRemote still selects");
    // The rule's other side: an upstream that is the destination still selects among several.
    wants_copy(copy_bent(vec![feature(Some(("upstream", "feature")))], two),
        "git -C '/fixture/repo' push -- 'upstream' 'feature'", "the same name, its real destination");
    wants_refusal(copy_bent(vec![feature(Some(("upstream", "main")))], |f| { two(f); f["pushesToUpstream"] = json!(true); }),
        "name-mismatch", "push.default upstream makes it the destination");
    // A `.` upstream is no remote, whatever its merge name, and however many remotes there are.
    wants_refusal(copy_bent(vec![feature(Some((".", "main")))], |_| {}), "no-remote", "a . upstream of another name");
    wants_refusal(copy_bent(vec![feature(Some((".", "main")))], two), "no-remote", "a . upstream of another name, two remotes");
    // The start point's remote is not selected, and its own facts are still read: a legacy one, or one the facts do not list.
    wants_refusal(copy_bent(vec![feature(Some(("old", "main")))], |f| {
        f["legacyNames"] = json!(["old"]);
        f["remotes"].as_array_mut().unwrap().push(json!({ "name": "old", "transport": null, "github": null, "vcs": false, "push": false,
            "configSection": false, "url": false, "legacy": true, "defaultBranch": null }));
        f["pushDefault"] = json!("origin");
    }), "name-mismatch", "a legacy start point beside a selected remote");
    wants_refusal(copy_bent(vec![feature(Some(("unlisted", "main")))], |_| {}), "ambiguous", "an unlisted start point");
}

/// A `branch.<n>.remote` or `.pushremote` holding a URL: the engine reports only that these facts are unknown, and the
/// nulls beside that say nothing. Above all they are not "no upstream": no `-u`, and no match by tip.
#[test]
fn post_cap_remote_facts_unknown_keeps_the_editor_and_takes_links_and_copy_away() {
    let unknown = |mut b: Value| { b["remoteFactsUnknown"] = json!(true); b };
    wants_refusal(copy_bent(vec![unknown(feature(None))], |_| {}), "ambiguous", "not a copy with -u");
    wants_refusal(copy_bent(vec![unknown(feature(None))], |f| f["remotes"] = json!([])), "ambiguous", "not no-remote: a URL is a destination");
    wants_refusal(copy_bent(vec![unknown(feature(None))], |f| f["pushDefault"] = json!("origin")), "ambiguous", "pushDefault does not settle it");
    let (reply, mut facts) = fx();
    assert!(left_off(&reply, &facts).iter().any(|w| w.starts_with("branch")), "the control: the card has a branch link");
    assert!(left_off(&reply, &facts).iter().any(|w| w.starts_with("compare")), "the control: the card has Compare");
    let branch = &mut facts[0]["branches"][0];
    assert_eq!(branch["name"], json!("feature/contract"));
    branch["upstreamRemote"] = Value::Null;
    branch["upstreamBranch"] = Value::Null;
    branch["remoteFactsUnknown"] = json!(true);
    // A remote branch of its name at its tip would answer the no-upstream path: unknown must not take it.
    let tip = branch["tip"].clone();
    facts[0]["remoteBranches"] = json!([{ "remote": "origin", "name": "feature/contract", "sha": tip }]);
    let words = left_off(&reply, &facts);
    assert!(words.iter().any(|w| w.starts_with("editor")), "the checkout still opens: {words:?}");
    for gone in ["branch", "compare", "copy"] {
        assert!(!words.iter().any(|w| w.starts_with(gone)), "{gone}: {words:?}");
    }
    assert!(!did(&reply, &facts).iter().any(|w| w.starts_with("branch")), "no row link either");
}

/// Plan §0: a selected remote decides the links, whatever the upstream is called and with no upstream at all. Every clause,
/// on facts git would not always leave. The fixture's flows are `round4_a_differently_named_upstream_…` above.
#[test]
fn round5_a_selected_remote_decides_the_links_whatever_the_upstream_is_called() {
    const ORIGIN: &str = "https://github.com/org/repo/tree/feat";
    const FORK: &str = "https://github.com/fork-org/repo/tree/feat";
    // What the branch's row opens: `feat` at `listed`, the tip being OTHER.
    let opens = |up: Option<(&str, &str)>, push: Option<&str>, default: Option<&str>, listed: &[(&str, &str)]| {
        let (mut reply, mut facts) = fx();
        with_rows(&mut reply, json!([{ "kind": "branch", "name": "feat", "push": null, "commits": [commit(PUSHED)] }]));
        reply["branchLines"] = json!([{ "key": "gui", "name": "feat", "state": "live", "notPushed": 1, "neverPushed": false, "behind": 0 }]);
        facts[0]["pushDefault"] = json!(default);
        facts[0]["remotes"] = json!([remote_entry("origin", "org"), remote_entry("fork", "fork-org")]);
        let mut branch = local_branch("feat", up, Some(OTHER));
        branch["pushRemote"] = json!(push);
        facts[0]["branches"] = json!([branch]);
        facts[0]["remoteBranches"] = listed.iter().map(|(remote, sha)| json!({ "remote": remote, "name": "feat", "sha": sha })).collect();
        opened_by(&minted(&reply, &facts), "did", "gui", "branch")
    };
    let same_name = Some(("origin", "feat"));
    let want = |url: &str| Some(url.to_string());
    // The selection decides, and pushRemote beats pushDefault both ways.
    assert_eq!(opens(same_name, Some("fork"), None, &[("origin", MAIN_TIP), ("fork", OTHER)]), want(FORK), "pushRemote");
    assert_eq!(opens(same_name, None, Some("fork"), &[("origin", MAIN_TIP), ("fork", OTHER)]), want(FORK), "pushDefault");
    assert_eq!(opens(same_name, Some("fork"), Some("origin"), &[("origin", MAIN_TIP), ("fork", OTHER)]), want(FORK), "pushRemote over pushDefault");
    assert_eq!(opens(same_name, Some("origin"), Some("fork"), &[("origin", MAIN_TIP), ("fork", OTHER)]), want(ORIGIN), "pushRemote names the upstream's remote, over pushDefault");
    // The same-name-at-tip rule, on the selected remote only: its branch must be at the tip, and the other remote's never counts.
    assert_eq!(opens(same_name, Some("fork"), None, &[("origin", OTHER)]), None, "only the upstream's holds it");
    assert_eq!(opens(same_name, Some("fork"), None, &[("origin", OTHER), ("fork", MAIN_TIP)]), None, "the selected remote's is behind");
    assert_eq!(opens(same_name, Some("fork"), None, &[("origin", OTHER), ("fork", OTHER)]), want(FORK), "both at the tip are not ambiguous");
    // No upstream: the same.
    assert_eq!(opens(None, Some("fork"), None, &[("origin", OTHER)]), None, "no upstream, pushRemote");
    assert_eq!(opens(None, None, Some("fork"), &[("origin", OTHER)]), None, "no upstream, pushDefault");
    assert_eq!(opens(None, Some("fork"), None, &[("origin", OTHER), ("fork", OTHER)]), want(FORK), "no upstream, both at the tip");
    // No selection: what it was. An upstream of its own name counts behind the tip, and without one any remote may hold the tip,
    // though two may not.
    assert_eq!(opens(same_name, None, None, &[("origin", MAIN_TIP), ("fork", OTHER)]), want(ORIGIN), "its own upstream");
    assert_eq!(opens(None, None, None, &[("fork", OTHER)]), want(FORK), "no upstream, one remote");
    assert_eq!(opens(None, None, None, &[("origin", OTHER), ("fork", OTHER)]), None, "no upstream, two remotes");
    assert_eq!(opens(Some(("origin", "develop")), None, None, &[("fork", OTHER)]), want(FORK), "only where it started");
}

/// A label-only card (no What-you-did card to name its repo) on a repo whose run record lists it (`cardKeys`).
fn label_only() -> (Value, Value) {
    let (mut reply, facts) = fx();
    reply["labels"] = json!([]);
    (reply, facts)
}

#[test]
fn round3_a_label_only_card_joins_its_repo_though_no_root_lists_it_and_only_the_editor_goes() {
    let (reply, mut facts) = label_only();
    let whole = left_off(&reply, &facts);
    assert!(whole.iter().any(|w| w.starts_with("editor")), "control: {whole:?}");
    // A detached checkout, or the label's folder absent from the checked-out branch: no root names the card.
    for roots in [json!([]), json!([{ "root": "", "project": facts[0]["roots"][0]["project"], "labelKeys": [], "displayLabel": null }])] {
        facts[0]["roots"] = roots;
        let shown = left_off(&reply, &facts);
        let without_editor: Vec<&String> = whole.iter().filter(|w| !w.starts_with("editor")).collect();
        assert_eq!(shown.iter().collect::<Vec<_>>(), without_editor, "{}", facts[0]["roots"]);
        assert!(shown.iter().any(|w| w == "branch") && shown.iter().any(|w| w.starts_with("compare")), "{shown:?}");
    }
}

#[test]
fn round3_the_card_join_needs_exactly_one_repo_that_lists_the_key() {
    // A record with no such key, or the engine's unknown, gives none.
    for keys in [json!([]), json!(["other"])] {
        let (reply, mut facts) = label_only();
        facts[0]["cardKeys"] = keys;
        assert_eq!(left_off(&reply, &facts), Vec::<String>::new());
    }
    // A key on two repos joins neither, and a repo whose keys are unknown cannot leave another unique.
    for other_keys in [json!(["gui"]), Value::Null] {
        let (reply, mut facts) = label_only();
        let mut other = facts[0].clone();
        other["repoKey"] = json!("rother");
        other["cardKeys"] = other_keys.clone();
        facts.as_array_mut().unwrap().push(other);
        assert_eq!(left_off(&reply, &facts), Vec::<String>::new(), "{other_keys}");
    }
}

#[test]
fn round3_a_commit_arrow_counts_repositories_not_remote_names() {
    let (mut reply, mut facts) = fx();
    with_rows(&mut reply, json!([{ "kind": "pr", "number": 12, "title": "t", "commits": [commit(PUSHED)] }]));
    facts[0]["remotes"] = json!([remote_entry("origin", "org"), remote_entry("origin-ssh", "ORG"), remote_entry("fork", "fork-org")]);
    let on = |names: Value, facts: &mut Value| {
        facts[0]["reachableRemotes"] = json!([{ "sha": PUSHED, "remotes": names }]);
    };
    // One repository under two names: the arrow stays, and the click agrees.
    on(json!(["origin", "origin-ssh"]), &mut facts);
    let out = minted(&reply, &facts);
    assert_eq!(opened_by(&out, "did", "gui", "commit"), Some(format!("https://github.com/org/repo/commit/{PUSHED}")));
    // Two repositories, with no row to choose: none.
    on(json!(["fork", "origin"]), &mut facts);
    assert_eq!(opened_by(&minted(&reply, &facts), "did", "gui", "commit"), None);
}

/// Plan §0, round 4: a deploy remote holding the commit costs it no arrow. Only remotes that read as GitHub can be opened, so
/// only they can be the choice.
#[test]
fn round4_a_commit_arrow_counts_only_remotes_that_read_as_github() {
    let (mut reply, mut facts) = fx();
    with_rows(&mut reply, json!([{ "kind": "pr", "number": 12, "title": "t", "commits": [commit(PUSHED)] }]));
    let mut heroku = remote_entry("heroku", "x");
    heroku["github"] = Value::Null;
    facts[0]["remotes"] = json!([remote_entry("origin", "org"), remote_entry("fork", "fork-org"), heroku]);
    let on = |names: Value, facts: &mut Value| {
        facts[0]["reachableRemotes"] = json!([{ "sha": PUSHED, "remotes": names }]);
    };
    on(json!(["heroku", "origin"]), &mut facts);
    let out = minted(&reply, &facts);
    assert_eq!(opened_by(&out, "did", "gui", "commit"), Some(format!("https://github.com/org/repo/commit/{PUSHED}")), "the arrow, and its click");
    // Alone on the deploy remote there is nothing to open, and two GitHub repositories still need a row to choose.
    on(json!(["heroku"]), &mut facts);
    assert_eq!(opened_by(&minted(&reply, &facts), "did", "gui", "commit"), None);
    on(json!(["fork", "heroku", "origin"]), &mut facts);
    assert_eq!(opened_by(&minted(&reply, &facts), "did", "gui", "commit"), None);
}

/// B2 `:39`: a clone that never checked out its default still has a remote counterpart for a `default` row.
#[test]
fn round3_a_default_row_with_no_local_default_uses_the_one_remote_whose_default_it_is() {
    let row = json!([{ "kind": "default", "name": "main", "push": null, "commits": [commit(MERGED)] }]);
    let (mut reply, mut facts) = fx();
    with_rows(&mut reply, row);
    facts[0]["branches"] = json!([local_branch("other", None, Some(OTHER))]);
    assert_eq!(opened_by(&minted(&reply, &facts), "did", "gui", "branch"), Some("https://github.com/org/repo/tree/main".to_string()));
    // Two remotes whose default is that name: no guess.
    let mut two = facts.clone();
    two[0]["remotes"].as_array_mut().unwrap().push(remote_entry("fork", "fork-org"));
    two[0]["remoteBranches"].as_array_mut().unwrap().push(json!({ "remote": "fork", "name": "main", "sha": MAIN_TIP }));
    assert_eq!(opened_by(&minted(&reply, &two), "did", "gui", "branch"), None);
    // That remote's own branch is not listed, its name is not the default, or the local list is unknown.
    let mut gone = facts.clone();
    gone[0]["remoteBranches"] = json!([]);
    assert_eq!(opened_by(&minted(&reply, &gone), "did", "gui", "branch"), None);
    let mut elsewhere = facts.clone();
    elsewhere[0]["remotes"][0]["defaultBranch"] = json!("trunk");
    assert_eq!(opened_by(&minted(&reply, &elsewhere), "did", "gui", "branch"), None);
    let mut unknown = facts.clone();
    unknown[0]["branches"] = Value::Null;
    assert_eq!(opened_by(&minted(&reply, &unknown), "did", "gui", "branch"), None);
    // A local default keeps deciding, even when it has no counterpart. A `branch` row of that name does not get this.
    let mut local = facts.clone();
    local[0]["branches"] = json!([local_branch("main", None, Some(OTHER))]);
    assert_eq!(opened_by(&minted(&reply, &local), "did", "gui", "branch"), None);
    with_rows(&mut reply, json!([{ "kind": "branch", "name": "main", "push": null, "commits": [commit(MERGED)] }]));
    assert_eq!(opened_by(&minted(&reply, &facts), "did", "gui", "branch"), None);
}
